bool debugEnabled() {
    static const bool enabled = getenv("LIBRECUDA_DEBUG") != nullptr && std::string(getenv("LIBRECUDA_DEBUG")) != "0";
    return enabled;
}

#define RT_DEBUG(...) do { if (debugEnabled()) { fprintf(stderr, "[LibreCuda Runtime]: " __VA_ARGS__); fputc('\n', stderr); } } while (0)

// a kernel failure (sticky error) was returned to the program
std::atomic<bool> g_kernelFailureReported{false};

cudaError_t recordError(cudaError_t error) {
    if (error != cudaSuccess) {
        t_lastError = error;
    }
    if (error == cudaErrorIllegalAddress || error == cudaErrorMisalignedAddress || error == cudaErrorLaunchFailure ||
        error == cudaErrorAssert || error == cudaErrorIllegalInstruction || error == cudaErrorInvalidAddressSpace ||
        error == cudaErrorInvalidPc) {
        g_kernelFailureReported = true;
    }
    return error;
}

cudaError_t mapStatus(libreCudaStatus_t status) {
    switch (status) {
        case 0:
            return cudaSuccess;
        case 1:
            return cudaErrorInvalidValue;
        case 2:
            return cudaErrorMemoryAllocation;
        case 3:
            return cudaErrorInitializationError;
        case 65:
            return cudaErrorLaunchMaxDepthExceeded;
        case 101:
            return cudaErrorInvalidDevice;
        case 200:
            return cudaErrorInvalidKernelImage;
        case 217:
            return cudaErrorPeerAccessUnsupported;
        case 201:
            return cudaErrorDeviceUninitialized;
        case 500:
            return cudaErrorSymbolNotFound;
        case 600:
            return cudaErrorNotReady;
        case 700:
            return cudaErrorIllegalAddress;
        case 701:
            return cudaErrorLaunchOutOfResources;
        case 702:
            return cudaErrorLaunchTimeout;
        case 704:
            return cudaErrorPeerAccessAlreadyEnabled;
        case 705:
            return cudaErrorPeerAccessNotEnabled;
        case 710:
            return cudaErrorAssert;
        case 715:
            return cudaErrorIllegalInstruction;
        case 716:
            return cudaErrorMisalignedAddress;
        case 717:
            return cudaErrorInvalidAddressSpace;
        case 718:
            return cudaErrorInvalidPc;
        case 801:
            return cudaErrorNotSupported;
        case 912:
            return cudaErrorInvalidClusterSize;
        case 719:
            return cudaErrorLaunchFailure;
        case 804:
            return cudaErrorCompatNotSupportedOnDevice;
        default:
            return cudaErrorUnknown;
    }
}

/**
 * Kernels that hit an SM exception (e.g. a misaligned address) are detected in the background, so a program that
 * synchronizes right after such a kernel may see success. Where the program can't be told anymore (reset, exit), check
 * synchronously and warn.
 */
void warnAboutUnreportedKernelFailure(int device) {
    if (g_kernelFailureReported) {
        return;
    }
    const libreCudaStatus_t status = libreCuCtxCheckErrors();
    if (status != 0) {
        const cudaError_t error = mapStatus(status);
        fprintf(stderr, "LibreCUDA: a kernel on device %d failed after the last synchronization: %s (%s)\n", device,
                cudaGetErrorName(error), cudaGetErrorString(error));
        g_kernelFailureReported = true;
    }
}

#define RT_CHECK(expr) do { cudaError_t rt_check_err = (expr); if (rt_check_err != cudaSuccess) { return recordError(rt_check_err); } } while (0)
#define LC_CHECK(expr) do { libreCudaStatus_t lc_check_status = (expr); if (lc_check_status != 0) { RT_DEBUG("%s failed with %d (%s:%d)", #expr, int(lc_check_status), __FILE__, __LINE__); return recordError(mapStatus(lc_check_status)); } } while (0)

cudaError_t initialize() {
    std::lock_guard init_lock(g_initMutex);
    if (g_initialized) {
        return g_initError;
    }
    g_initialized = true;
    if (libreCuInit(0) != 0) {
        g_initError = cudaErrorNoDevice;
        return g_initError;
    }
    int count = 0;
    if (libreCuDeviceGetCount(&count) != 0 || count == 0) {
        g_initError = cudaErrorNoDevice;
        return g_initError;
    }
    g_devices.resize(count);
    for (int i = 0; i < count; i++) {
        libreCuDeviceGet(&g_devices[i].device, i);
    }
    return cudaSuccess;
}

cudaError_t newStream(int device, bool isDefault, bool blocking, CUstream_st **pOut) {
    LibreCUstream stream{};
    LC_CHECK(libreCuStreamCreate(&stream, 0));
    LibreCUEvent tail{};
    LC_CHECK(libreCuEventCreate(&tail, 0));
    *pOut = new CUstream_st{
        .device = device,
        .stream = stream,
        .isDefault = isDefault,
        .blocking = blocking,
        .dirty = false,
        .seenDefaultEpoch = 0,
        .defaultEpoch = 0,
        .tail = tail
    };
    return cudaSuccess;
}

/**
 * Makes the device's context current, creating it (and the device's default stream) on first use.
 */
cudaError_t activateDevice(int ordinal) {
    std::lock_guard init_lock(g_initMutex);
    RT_CHECK(initialize());
    if (ordinal < 0 || ordinal >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    DeviceState &state = g_devices[ordinal];
    if (state.ctx == nullptr) {
        LC_CHECK(libreCuCtxCreate_v2(&state.ctx, 0, state.device));
        LC_CHECK(libreCuDeviceGetAttribute(&state.ccMajor, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR, state.device));
        LC_CHECK(libreCuDeviceGetAttribute(&state.ccMinor, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR, state.device));
        RT_CHECK(newStream(ordinal, true, true, &state.defaultStream));
    } else {
        LC_CHECK(libreCuCtxSetCurrent(state.ctx));
    }
    return cudaSuccess;
}

cudaError_t activateCurrentDevice() {
    return activateDevice(t_device);
}

/**
 * Resolves a stream handle (including the special handles 0, cudaStreamLegacy and cudaStreamPerThread)
 * and makes its device current.
 */
cudaError_t resolveStream(cudaStream_t handle, CUstream_st **pOut) {
    if (handle == nullptr || handle == cudaStreamLegacy || handle == cudaStreamPerThread) {
        RT_CHECK(activateCurrentDevice());
        *pOut = g_devices[t_device].defaultStream;
        return cudaSuccess;
    }
    RT_CHECK(activateDevice(handle->device));
    *pOut = handle;
    return cudaSuccess;
}

/**
 * Implements the implicit synchronization of the legacy default stream: work on the default stream waits for all
 * blocking streams, work on blocking streams waits for the default stream. Waits happen on the GPU.
 */
cudaError_t beginOperation(CUstream_st *stream) {
    DeviceState &state = g_devices[stream->device];
    if (stream->isDefault) {
        RT_CHECK(checkImplicitCapture(stream->device));
        for (CUstream_st *other: state.streams) {
            if (other->blocking && other->dirty) {
                LC_CHECK(libreCuEventRecord(other->tail, other->stream));
                LC_CHECK(libreCuStreamCommence(other->stream));
                LC_CHECK(libreCuStreamWaitEvent(stream->stream, other->tail));
                other->dirty = false;
            }
        }
    } else if (stream->blocking) {
        CUstream_st *def = state.defaultStream;
        // other blocking streams may do this at the same time (work on the default stream itself is exclusive)
        StreamStateLock def_lock(def);
        if (stream->seenDefaultEpoch != def->defaultEpoch) {
            LC_CHECK(libreCuEventRecord(def->tail, def->stream));
            LC_CHECK(libreCuStreamCommence(def->stream));
            LC_CHECK(libreCuStreamWaitEvent(stream->stream, def->tail));
            stream->seenDefaultEpoch = def->defaultEpoch;
        }
    }
    return cudaSuccess;
}

/**
 * Submits the enqueued work of the stream to the GPU
 */
cudaError_t endOperation(CUstream_st *stream) {
    if (stream->isDefault) {
        stream->defaultEpoch++;
    } else {
        stream->dirty = true;
    }
    LC_CHECK(libreCuStreamCommence(stream->stream));
    return cudaSuccess;
}

cudaError_t synchronizeStream(CUstream_st *stream) {
    LibreCUstream driver_stream = stream->stream;
    LC_CHECK(blocking([driver_stream] { return libreCuStreamAwait(driver_stream); }));
    if (!stream->isDefault) {
        StreamStateLock state_lock(stream);
        stream->dirty = false;
    }
    return cudaSuccess;
}

cudaError_t synchronizeDevice(int ordinal) {
    DeviceState &state = g_devices[ordinal];
    if (state.ctx == nullptr) {
        return cudaSuccess;
    }
    RT_CHECK(synchronizeStream(state.defaultStream));
    // other threads may create and destroy streams while this one waits without the API lock
    const std::vector<CUstream_st *> streams = state.streams;
    for (CUstream_st *stream: streams) {
        if (std::find(state.streams.begin(), state.streams.end(), stream) != state.streams.end()) {
            RT_CHECK(synchronizeStream(stream));
        }
    }
    return cudaSuccess;
}

/**
 * Destroys the device's context with all its streams, events, modules and memory. The next use of the device creates
 * a new context. Handles of destroyed streams are invalid afterwards; destroyed events can still be passed to
 * cudaEventDestroy.
 */
cudaError_t resetDevice(int ordinal) {
    DeviceState &state = g_devices[ordinal];
    if (state.ctx == nullptr) {
        return cudaSuccess;
    }
    LC_CHECK(libreCuCtxSetCurrent(state.ctx));
    // errors of earlier work must not prevent the reset
    synchronizeDevice(ordinal);
    warnAboutUnreportedKernelFailure(ordinal);
    LIFETIME_LOCK();

    for (CUevent_st *event: state.events) {
        libreCuEventDestroy(event->event);
        event->event = nullptr;
    }
    state.events.clear();
    for (cudaArray *array: state.arrays) {
        libreCuArrayDestroy(array->array);
        array->array = nullptr;
    }
    state.arrays.clear();
    for (cudaMipmappedArray *mipmapped: state.mipmappedArrays) {
        libreCuArrayDestroy(mipmapped->all.array);
        mipmapped->all.array = nullptr;
        for (cudaArray *level: mipmapped->levels) {
            level->array = nullptr;
        }
    }
    state.mipmappedArrays.clear();
    state.streams.push_back(state.defaultStream);
    for (CUstream_st *stream: state.streams) {
        leaveCapture(stream);
    }
    for (CUstream_st *stream: state.streams) {
        libreCuEventDestroy(stream->tail);
        libreCuStreamDestroy(stream->stream);
        delete stream;
    }
    state.streams.clear();
    state.defaultStream = nullptr;

    for (FatbinRecord *fatbin: g_fatbins) {
        auto it = fatbin->modules.find(ordinal);
        if (it != fatbin->modules.end()) {
            libreCuModuleUnload(it->second);
            fatbin->modules.erase(it);
        }
    }
    for (auto &[stub, kernel]: g_kernels) {
        kernel->functions.erase(ordinal);
        kernel->paramCounts.erase(ordinal);
    }

    LC_CHECK(libreCuCtxDestroy(state.ctx));
    state.ctx = nullptr;
    state.generation++;
    return cudaSuccess;
}

// ---------------------------------------------------------------------------------------------------------------------
// fat binaries

struct FatbinWrapper {
    int magic;
    int version;
    const unsigned long long *data;
    void *filename_or_fatbins;
};

constexpr int FATBIN_WRAPPER_MAGIC = 0x466243b1;
constexpr uint32_t FATBIN_MAGIC = 0xba55ed50;

constexpr uint16_t FATBIN_KIND_PTX = 1;
constexpr uint16_t FATBIN_KIND_ELF = 2;

constexpr uint64_t FATBIN_FLAG_COMPRESSED_LZ4 = 0x2000;
constexpr uint64_t FATBIN_FLAG_COMPRESSED_ZSTD = 0x8000;

#pragma pack(push, 1)
struct FatbinHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t headerSize;
    uint64_t fatSize;
};

struct FatbinEntryHeader {
    uint16_t kind;
    uint16_t version;
    uint32_t headerSize;
    uint64_t paddedPayloadSize;
    uint32_t compressedSize;
    uint32_t unknown0;
    uint32_t binaryVersion;
    uint32_t arch;
    uint64_t unknown1;
    uint64_t flags;
    uint64_t unknown2;
    uint64_t uncompressedSize;
};
#pragma pack(pop)

struct FatbinEntry {
    uint16_t kind;
    uint32_t arch;
    const FatbinEntryHeader *header;
    const uint8_t *payload;
};

std::vector<FatbinEntry> parseFatbin(const void *data) {
    std::vector<FatbinEntry> entries{};
    const auto *header = static_cast<const FatbinHeader *>(data);
    if (header->magic != FATBIN_MAGIC) {
        return entries;
    }
    const auto *base = static_cast<const uint8_t *>(data) + header->headerSize;
    const uint8_t *end = base + header->fatSize;
    for (const uint8_t *p = base; p + sizeof(FatbinEntryHeader) <= end;) {
        const auto *entry = reinterpret_cast<const FatbinEntryHeader *>(p);
        if (entry->headerSize == 0) {
            break;
        }
        entries.push_back(FatbinEntry{
            .kind = entry->kind,
            .arch = entry->arch,
            .header = entry,
            .payload = p + entry->headerSize
        });
        p += entry->headerSize + entry->paddedPayloadSize;
    }
    return entries;
}

cudaError_t entryPayload(const FatbinEntry &entry, std::vector<uint8_t> &out) {
    const auto *h = entry.header;
    if (h->flags & FATBIN_FLAG_COMPRESSED_ZSTD) {
        out.resize(h->uncompressedSize);
        const size_t compressed = h->compressedSize != 0 ? h->compressedSize : h->paddedPayloadSize;
        size_t n = ZSTD_decompress(out.data(), out.size(), entry.payload, compressed);
        if (ZSTD_isError(n)) {
            RT_DEBUG("zstd decompression of fatbin entry failed: %s", ZSTD_getErrorName(n));
            return cudaErrorInvalidKernelImage;
        }
        out.resize(n);
    } else if (h->flags & FATBIN_FLAG_COMPRESSED_LZ4) {
        RT_DEBUG("fatbin entry uses unsupported legacy compression; compile with -Xfatbin=-compress-all=false "
                 "or --compress-mode=none");
        return cudaErrorInvalidKernelImage;
    } else {
        size_t n = h->compressedSize != 0 ? h->compressedSize : h->paddedPayloadSize;
        if (h->uncompressedSize != 0) {
            n = std::min<size_t>(n, h->uncompressedSize);
        }
        out.assign(entry.payload, entry.payload + h->paddedPayloadSize);
        (void) n;
    }
    return cudaSuccess;
}

std::string findPtxas() {
    std::vector<std::string> candidates{};
    if (const char *env = getenv("LIBRECUDA_PTXAS")) {
        candidates.emplace_back(env);
    }
    for (const char *var: {"CUDA_HOME", "CUDA_PATH"}) {
        if (const char *env = getenv(var)) {
            candidates.push_back(std::string(env) + "/bin/ptxas");
        }
    }
    candidates.emplace_back("/usr/local/cuda/bin/ptxas");
    if (const char *path = getenv("PATH")) {
        std::stringstream ss(path);
        std::string dir;
        while (std::getline(ss, dir, ':')) {
            candidates.push_back(dir + "/ptxas");
        }
    }
    for (const auto &candidate: candidates) {
        if (access(candidate.c_str(), X_OK) == 0) {
            return candidate;
        }
    }
    return "";
}

/**
 * Compiles PTX for the device with the ptxas assembler of an installed CUDA toolkit.
 * Results are cached in $XDG_CACHE_HOME/librecuda (or ~/.cache/librecuda).
 */
cudaError_t compilePtx(const std::vector<uint8_t> &ptx, int smVersion, std::vector<uint8_t> &cubinOut) {
    std::string cache_dir;
    if (const char *xdg = getenv("XDG_CACHE_HOME")) {
        cache_dir = std::string(xdg) + "/librecuda";
    } else if (const char *home = getenv("HOME")) {
        cache_dir = std::string(home) + "/.cache/librecuda";
    } else {
        cache_dir = "/tmp/librecuda-cache";
    }
    mkdir(cache_dir.substr(0, cache_dir.rfind('/')).c_str(), 0755);
    mkdir(cache_dir.c_str(), 0755);

    const std::string ptx_str(ptx.begin(), std::find(ptx.begin(), ptx.end(), 0));
    const size_t hash = std::hash<std::string>{}(ptx_str + "|sm_" + std::to_string(smVersion));
    char hash_hex[32];
    snprintf(hash_hex, sizeof(hash_hex), "%016zx", hash);
    const std::string cubin_path = cache_dir + "/" + hash_hex + "_sm" + std::to_string(smVersion) + ".cubin";

    std::ifstream cached(cubin_path, std::ios::binary);
    if (!cached.good()) {
        const std::string ptxas = findPtxas();
        if (ptxas.empty()) {
            RT_DEBUG("no SASS for sm_%d in the fat binary and no ptxas found to compile its PTX", smVersion);
            return cudaErrorNoKernelImageForDevice;
        }
        const std::string ptx_path = cache_dir + "/" + hash_hex + ".ptx";
        {
            std::ofstream out(ptx_path, std::ios::binary);
            out << ptx_str;
        }
        const std::string tmp_cubin = cubin_path + ".tmp" + std::to_string(getpid());
        const std::string arch = "-arch=sm_" + std::to_string(smVersion);
        pid_t pid = fork();
        if (pid == 0) {
            execl(ptxas.c_str(), ptxas.c_str(), arch.c_str(), "-O3", ptx_path.c_str(), "-o", tmp_cubin.c_str(),
                  static_cast<char *>(nullptr));
            _exit(127);
        }
        int status = 0;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            RT_DEBUG("ptxas failed to compile PTX for sm_%d", smVersion);
            return cudaErrorInvalidPtx;
        }
        rename(tmp_cubin.c_str(), cubin_path.c_str());
        cached = std::ifstream(cubin_path, std::ios::binary);
    }
    cubinOut.assign(std::istreambuf_iterator<char>(cached), std::istreambuf_iterator<char>());
    return cudaSuccess;
}

/**
 * Picks the best image of a fat binary for the device: SASS of the same architecture (or an older minor version of
 * the same major), otherwise the newest compatible PTX compiled with ptxas.
 */
cudaError_t selectImage(const void *fatbinData, int ccMajor, int ccMinor, std::vector<uint8_t> &imageOut) {
    const uint32_t sm = ccMajor * 10 + ccMinor;
    const auto entries = parseFatbin(fatbinData);
    const FatbinEntry *best_elf = nullptr;
    const FatbinEntry *best_ptx = nullptr;
    for (const auto &entry: entries) {
        if (entry.kind == FATBIN_KIND_ELF && entry.arch / 10 == sm / 10 && entry.arch <= sm) {
            if (best_elf == nullptr || entry.arch > best_elf->arch) {
                best_elf = &entry;
            }
        } else if (entry.kind == FATBIN_KIND_PTX && entry.arch <= sm) {
            if (best_ptx == nullptr || entry.arch > best_ptx->arch) {
                best_ptx = &entry;
            }
        }
    }
    if (best_elf != nullptr) {
        return entryPayload(*best_elf, imageOut);
    }
    if (best_ptx != nullptr) {
        std::vector<uint8_t> ptx;
        RT_CHECK(entryPayload(*best_ptx, ptx));
        return compilePtx(ptx, static_cast<int>(sm), imageOut);
    }
    RT_DEBUG("fat binary contains no image usable on sm_%u", sm);
    return cudaErrorNoKernelImageForDevice;
}

cudaError_t moduleForDevice(FatbinRecord *fatbin, int device, LibreCUmodule *pModuleOut) {
    std::lock_guard module_lock(g_moduleMutex);
    auto it = fatbin->modules.find(device);
    if (it != fatbin->modules.end()) {
        *pModuleOut = it->second;
        return cudaSuccess;
    }
    const auto *wrapper = static_cast<const FatbinWrapper *>(fatbin->wrapper);
    const void *data = wrapper;
    if (wrapper->magic == FATBIN_WRAPPER_MAGIC) {
        data = wrapper->data;
    }
    const DeviceState &state = g_devices[device];
    std::vector<uint8_t> image;
    RT_CHECK(selectImage(data, state.ccMajor, state.ccMinor, image));
    LibreCUmodule module{};
    LC_CHECK(libreCuModuleLoadData(&module, image.data(), image.size()));
    fatbin->modules[device] = module;
    *pModuleOut = module;
    return cudaSuccess;
}

cudaError_t kernelFunction(KernelRecord *kernel, int device, LibreCUFunction *pFunctionOut, size_t *pParamCount) {
    std::lock_guard module_lock(g_moduleMutex);
    auto it = kernel->functions.find(device);
    if (it != kernel->functions.end()) {
        *pFunctionOut = it->second;
        *pParamCount = kernel->paramCounts[device];
        return cudaSuccess;
    }
    LibreCUmodule module{};
    RT_CHECK(moduleForDevice(kernel->fatbin, device, &module));
    LibreCUFunction function{};
    if (libreCuModuleGetFunction(&function, module, kernel->name.c_str()) != 0) {
        RT_DEBUG("kernel %s not found in module", kernel->name.c_str());
        return recordError(cudaErrorInvalidDeviceFunction);
    }
    size_t param_count{};
    LC_CHECK(libreCuFuncGetParamCount(&param_count, function));
    kernel->functions[device] = function;
    kernel->paramCounts[device] = param_count;
    *pFunctionOut = function;
    *pParamCount = param_count;
    return cudaSuccess;
}

cudaError_t lookupKernel(const void *func, KernelRecord **pOut) {
    auto it = g_kernels.find(func);
    if (it != g_kernels.end()) {
        *pOut = it->second;
        return cudaSuccess;
    }
    // the cudaKernel_t handle returned by __cudaGetKernel is the record itself
    for (const auto &[stub, record]: g_kernels) {
        if (record == func) {
            *pOut = record;
            return cudaSuccess;
        }
    }
    return recordError(cudaErrorInvalidDeviceFunction);
}

cudaError_t currentFunction(const void *func, LibreCUFunction *pOut) {
    KernelRecord *kernel{};
    RT_CHECK(lookupKernel(func, &kernel));
    RT_CHECK(activateCurrentDevice());
    size_t param_count{};
    return kernelFunction(kernel, t_device, pOut, &param_count);
}

cudaError_t symbolAddress(const void *symbol, void **pDevicePtr, size_t *pSize) {
    auto it = g_vars.find(symbol);
    if (it == g_vars.end()) {
        return recordError(cudaErrorInvalidSymbol);
    }
    RT_CHECK(activateCurrentDevice());
    LibreCUmodule module{};
    RT_CHECK(moduleForDevice(it->second.fatbin, t_device, &module));
    LC_CHECK(libreCuModuleGetGlobal(pDevicePtr, pSize, module, it->second.name.c_str()));
    return cudaSuccess;
}

/**
 * Cluster dimensions of a launch configuration: the launch attribute, else the kernel's compiled __cluster_dims__
 */
/**
 * The attributes of a function (cudaFuncGetAttributes without the API lock)
 */
void functionAttributes(LibreCUFunction function, cudaFuncAttributes *attr) {
    memset(attr, 0, sizeof(*attr));
    int value{};
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_SHARED_SIZE_BYTES, function);
    attr->sharedSizeBytes = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_CONST_SIZE_BYTES, function);
    attr->constSizeBytes = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_LOCAL_SIZE_BYTES, function);
    attr->localSizeBytes = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_MAX_THREADS_PER_BLOCK, function);
    attr->maxThreadsPerBlock = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_NUM_REGS, function);
    attr->numRegs = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_PTX_VERSION, function);
    attr->ptxVersion = value;
    attr->binaryVersion = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, function);
    attr->maxDynamicSharedSizeBytes = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_CLUSTER_SIZE_MUST_BE_SET, function);
    attr->clusterDimMustBeSet = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_WIDTH, function);
    attr->requiredClusterWidth = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_HEIGHT, function);
    attr->requiredClusterHeight = value;
    libreCuFuncGetAttribute(&value, CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_DEPTH, function);
    attr->requiredClusterDepth = value;
    attr->clusterSchedulingPolicyPreference = 0;
    attr->nonPortableClusterSizeAllowed = 0;
    attr->preferredShmemCarveout = -1;
}

/**
 * Blocks of the function that fit on one SM at once (cudaOccupancyMaxActiveBlocksPerMultiprocessor without the API
 * lock)
 */
void occupancyOf(LibreCUFunction function, int device, int blockSize, size_t dynamicSMemSize, int *numBlocks) {
    LibreCUdevice dev = g_devices[device].device;
    int regs{}, static_smem{}, max_threads{};
    libreCuFuncGetAttribute(&regs, CU_FUNC_ATTRIBUTE_NUM_REGS, function);
    libreCuFuncGetAttribute(&static_smem, CU_FUNC_ATTRIBUTE_SHARED_SIZE_BYTES, function);
    libreCuFuncGetAttribute(&max_threads, CU_FUNC_ATTRIBUTE_MAX_THREADS_PER_BLOCK, function);
    if (blockSize > max_threads) {
        *numBlocks = 0;
        return;
    }
    int max_threads_sm{}, max_blocks_sm{}, regs_sm{}, smem_sm{}, reserved_smem{};
    libreCuDeviceGetAttribute(&max_threads_sm, CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_MULTIPROCESSOR, dev);
    libreCuDeviceGetAttribute(&max_blocks_sm, CU_DEVICE_ATTRIBUTE_MAX_BLOCKS_PER_MULTIPROCESSOR, dev);
    libreCuDeviceGetAttribute(&regs_sm, CU_DEVICE_ATTRIBUTE_MAX_REGISTERS_PER_MULTIPROCESSOR, dev);
    libreCuDeviceGetAttribute(&smem_sm, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_MULTIPROCESSOR, dev);
    libreCuDeviceGetAttribute(&reserved_smem, CU_DEVICE_ATTRIBUTE_RESERVED_SHARED_MEMORY_PER_BLOCK, dev);

    const int warps_per_block = (blockSize + 31) / 32;
    int blocks = std::min(max_blocks_sm, (max_threads_sm / 32) / warps_per_block);
    const int regs_per_warp = ((std::max(1, regs) * 32 + 255) / 256) * 256;
    blocks = std::min(blocks, regs_sm / (regs_per_warp * warps_per_block));
    const size_t smem_per_block = ((static_smem + dynamicSMemSize + reserved_smem + 127) / 128) * 128;
    if (smem_per_block > 0) {
        blocks = std::min<int>(blocks, static_cast<int>(smem_sm / smem_per_block));
    }
    *numBlocks = std::max(0, blocks);
}

static dim3 clusterDimsOf(const void *func, const cudaLaunchConfig_t *config) {
    for (unsigned int i = 0; i < config->numAttrs; i++) {
        if (config->attrs[i].id == cudaLaunchAttributeClusterDimension) {
            const auto &d = config->attrs[i].val.clusterDim;
            return dim3(d.x, d.y, d.z);
        }
    }
    LibreCUFunction function{};
    if (currentFunction(func, &function) == cudaSuccess) {
        cudaFuncAttributes attrs{};
        functionAttributes(function, &attrs);
        if (attrs.requiredClusterWidth > 0) {
            return dim3(attrs.requiredClusterWidth, attrs.requiredClusterHeight, attrs.requiredClusterDepth);
        }
    }
    return dim3(1, 1, 1);
}

/**
 * Blocks of the configuration that fit on one GPC at once (a cluster runs within one GPC), and the GPC count
 */
static cudaError_t blocksPerGpc(const void *func, const cudaLaunchConfig_t *config, int *pBlocks, int *pGpcs) {
    int blocks_per_sm{};
    const int block_size = static_cast<int>(config->blockDim.x * config->blockDim.y * config->blockDim.z);
    LibreCUFunction function{};
    RT_CHECK(currentFunction(func, &function));
    occupancyOf(function, t_device, block_size, config->dynamicSmemBytes, &blocks_per_sm);
    LibreCUdevice dev = g_devices[t_device].device;
    int sm_count{}, gpcs{};
    LC_CHECK(libreCuDeviceGetAttribute(&sm_count, CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT, dev));
    LC_CHECK(libreCuDeviceGetAttribute(&gpcs, LIBRECUDA_DEVICE_ATTRIBUTE_GPC_COUNT, dev));
    gpcs = std::max(1, gpcs);
    // SMs may be distributed unevenly over the GPCs; assume the average
    *pBlocks = blocks_per_sm * (sm_count / gpcs);
    *pGpcs = gpcs;
    return cudaSuccess;
}

cudaError_t launch(const void *func, dim3 grid, dim3 block, void **args, size_t sharedMem, cudaStream_t handle,
                   bool cooperative = false, const dim3 *cluster = nullptr) {
    KernelRecord *kernel{};
    RT_CHECK(lookupKernel(func, &kernel));
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (capturing(stream)) {
        return captureKernel(stream, func, grid, block, args, sharedMem, cooperative, cluster);
    }
    LibreCUFunction function{};
    size_t param_count{};
    RT_CHECK(kernelFunction(kernel, stream->device, &function, &param_count));
    if (cooperative) {
        // a grid wide barrier deadlocks unless all blocks are resident at the same time
        int blocks_per_sm{}, sm_count{};
        occupancyOf(function, stream->device, static_cast<int>(block.x * block.y * block.z), sharedMem,
                    &blocks_per_sm);
        LC_CHECK(libreCuDeviceGetAttribute(&sm_count, CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT,
                                           g_devices[stream->device].device));
        if (uint64_t(grid.x) * grid.y * grid.z > uint64_t(blocks_per_sm) * sm_count) {
            return recordError(cudaErrorCooperativeLaunchTooLarge);
        }
    }
    RT_CHECK(beginOperation(stream));
    if (cooperative && cluster != nullptr) {
        return recordError(cudaErrorNotSupported);
    }
    {
        // a cluster that can't be resident on one GPC would never be scheduled: reject it like CUDA
        cudaLaunchAttribute attribute{};
        cudaLaunchConfig_t config{};
        config.blockDim = block;
        config.dynamicSmemBytes = sharedMem;
        if (cluster != nullptr) {
            attribute.id = cudaLaunchAttributeClusterDimension;
            attribute.val.clusterDim.x = cluster->x;
            attribute.val.clusterDim.y = cluster->y;
            attribute.val.clusterDim.z = cluster->z;
            config.attrs = &attribute;
            config.numAttrs = 1;
        }
        const dim3 dims = clusterDimsOf(func, &config);
        const int cluster_size = static_cast<int>(dims.x * dims.y * dims.z);
        if (cluster_size > 1) {
            int blocks_per_gpc{}, gpcs{};
            RT_CHECK(blocksPerGpc(func, &config, &blocks_per_gpc, &gpcs));
            if (blocks_per_gpc < cluster_size) {
                return recordError(cudaErrorInvalidClusterSize);
            }
        }
    }
    if (cooperative) {
        LC_CHECK(libreCuLaunchCooperativeKernel(function, grid.x, grid.y, grid.z, block.x, block.y, block.z,
                                                static_cast<uint32_t>(sharedMem), stream->stream, args, param_count));
    } else if (cluster != nullptr) {
        LC_CHECK(libreCuLaunchKernelCluster(function, grid.x, grid.y, grid.z, block.x, block.y, block.z,
                                            cluster->x, cluster->y, cluster->z, static_cast<uint32_t>(sharedMem),
                                            stream->stream, args, param_count));
    } else {
        bool launches_kernels = false;
        LC_CHECK(libreCuFuncGetLaunchesKernels(&launches_kernels, function));
        auto launch = [&] {
            return libreCuLaunchKernel(function, grid.x, grid.y, grid.z, block.x, block.y, block.z,
                                       static_cast<uint32_t>(sharedMem), stream->stream, args, param_count, nullptr,
                                       false);
        };
        // a kernel launching kernels from the device: the launch waits for them
        LC_CHECK(launches_kernels ? blocking(launch) : launch());
        if (launches_kernels) {
            RT_CHECK(endOperation(stream));
            return runDeviceGraphLaunches(handle);
        }
    }
    return endOperation(stream);
}

enum class PtrKind {
    // MANAGED: UVM managed memory, accessible from the CPU and every GPU (BAR1 managed memory is DEVICE memory)
    DEVICE, PINNED, MANAGED, PAGEABLE
};

PtrKind classify(const void *ptr) {
    if (libreCuMemIsDevice(ptr)) {
        return PtrKind::DEVICE;
    }
    if (libreCuMemIsPinnedHost(ptr)) {
        return PtrKind::PINNED;
    }
    if (libreCuMemIsManaged(ptr)) {
        return PtrKind::MANAGED;
    }
    return PtrKind::PAGEABLE;
}

/**
 * The device whose context allocated ptr (device or page-locked host memory); -1 for other memory
 */
int ownerDevice(const void *ptr) {
    LibreCUcontext ctx = libreCuMemGetContext(ptr);
    for (size_t i = 0; ctx != nullptr && i < g_devices.size(); i++) {
        if (g_devices[i].ctx == ctx) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

/**
 * Whether the stream's GPU can access device memory at ptr (its own, or a peer's with peer access enabled)
 */
bool accessibleFrom(const void *ptr, CUstream_st *stream) {
    return libreCuMemIsAccessibleFrom(ptr, g_devices[stream->device].ctx);
}

/**
 * A copy involving device memory of another device the stream's GPU can't access: the owning devices' GPUs copy
 * through host memory. Completes before returning; synchronous calls (holding the API lock exclusively) also wait
 * for all work of the devices involved, asynchronous ones for the stream's work.
 */
cudaError_t copyBetweenDevices(void *dst, const void *src, size_t count, CUstream_st *stream) {
    const PtrKind dst_kind = classify(dst), src_kind = classify(src);
    const auto copyingDevice = [&](const void *ptr, PtrKind kind) {
        return kind != PtrKind::DEVICE || accessibleFrom(ptr, stream) ? stream->device : ownerDevice(ptr);
    };
    const int src_device = copyingDevice(src, src_kind), dst_device = copyingDevice(dst, dst_kind);
    if (src_device < 0 || dst_device < 0) {
        return recordError(cudaErrorInvalidValue);
    }
    if (t_apiExclusiveDepth > 0) {
        for (int device: {stream->device, src_device, dst_device}) {
            RT_CHECK(synchronizeDevice(device));
        }
    } else {
        RT_CHECK(synchronizeStream(stream));
    }
    // a copy on the given device's GPU, waiting for it
    const auto copyOn = [&](int device, void *to, const void *from, size_t n) {
        LibreCUstream driver_stream = device == stream->device ? stream->stream : g_devices[device].defaultStream->stream;
        libreCudaStatus_t status = libreCuCtxSetCurrent(g_devices[device].ctx);
        if (status == 0) {
            status = blocking([&] { return libreCuMemCpy(to, const_cast<void *>(from), n, driver_stream, false); });
        }
        libreCuCtxSetCurrent(g_devices[stream->device].ctx);
        return status;
    };
    if (src_kind != PtrKind::DEVICE || dst_kind != PtrKind::DEVICE) {
        // one side is host memory: the device memory's owner copies directly
        LC_CHECK(copyOn(src_kind == PtrKind::DEVICE ? src_device : dst_device, dst, src, count));
        return cudaSuccess;
    }
    constexpr size_t BOUNCE_SIZE = 64 << 20;
    std::vector<uint8_t> bounce(std::min(count, BOUNCE_SIZE));
    for (size_t offset = 0; offset < count; offset += bounce.size()) {
        const size_t n = std::min(count - offset, bounce.size());
        LC_CHECK(copyOn(src_device, bounce.data(), static_cast<const uint8_t *>(src) + offset, n));
        LC_CHECK(copyOn(dst_device, static_cast<uint8_t *>(dst) + offset, bounce.data(), n));
    }
    return cudaSuccess;
}

cudaError_t memcpyOnStream(void *dst, const void *src, size_t count, CUstream_st *stream, bool synchronous) {
    if (count == 0) {
        return cudaSuccess;
    }
    const PtrKind dst_kind = classify(dst), src_kind = classify(src);
    const bool other_device = (dst_kind == PtrKind::DEVICE && !accessibleFrom(dst, stream)) ||
                              (src_kind == PtrKind::DEVICE && !accessibleFrom(src, stream));
    if (capturing(stream)) {
        // synchronous copies and pageable memory (staged, synchronous) can't be captured
        if (synchronous || dst_kind == PtrKind::PAGEABLE || src_kind == PtrKind::PAGEABLE) {
            return captureUnsupported(stream);
        }
        cudaMemcpy3DParms p{};
        p.dstPtr = cudaPitchedPtr{dst, count, count, 1};
        p.srcPtr = cudaPitchedPtr{const_cast<void *>(src), count, count, 1};
        p.extent = cudaExtent{count, 1, 1};
        p.kind = cudaMemcpyDefault;
        return captureCopy(stream, p);
    }
    if (other_device) {
        return copyBetweenDevices(dst, src, count, stream);
    }
    if (dst_kind == PtrKind::PAGEABLE && src_kind == PtrKind::PAGEABLE) {
        // host to host copies are stream ordered
        RT_CHECK(synchronizeStream(stream));
        memcpy(dst, src, count);
        return cudaSuccess;
    }
    RT_CHECK(beginOperation(stream));
    // copies involving pageable memory are staged and complete before returning
    const bool async = dst_kind != PtrKind::PAGEABLE && src_kind != PtrKind::PAGEABLE;
    LibreCUstream driver_stream = stream->stream;
    if (async) {
        LC_CHECK(libreCuMemCpy(dst, const_cast<void *>(src), count, driver_stream, true));
    } else {
        LC_CHECK(blocking([&] { return libreCuMemCpy(dst, const_cast<void *>(src), count, driver_stream, false); }));
    }
    RT_CHECK(endOperation(stream));
    if (synchronous) {
        RT_CHECK(synchronizeStream(stream));
    }
    return cudaSuccess;
}

cudaError_t memsetOnStream(void *dst, int value, size_t count, CUstream_st *stream, bool synchronous) {
    if (count == 0) {
        return cudaSuccess;
    }
    if (classify(dst) == PtrKind::PAGEABLE) {
        return recordError(cudaErrorInvalidValue);
    }
    if (classify(dst) == PtrKind::DEVICE && !accessibleFrom(dst, stream)) {
        // another device's memory without peer access (as NVIDIA's runtime)
        return recordError(cudaErrorInvalidValue);
    }
    if (capturing(stream)) {
        if (synchronous) {
            return captureUnsupported(stream);
        }
        return captureMemset(stream, cudaMemsetParams{dst, count, static_cast<unsigned int>(value) & 0xff, 1, count,
                                                      1});
    }
    RT_CHECK(beginOperation(stream));
    LC_CHECK(libreCuMemsetAsync(dst, static_cast<uint32_t>(value) & 0xff, 1, count, stream->stream));
    RT_CHECK(endOperation(stream));
    if (synchronous) {
        RT_CHECK(synchronizeStream(stream));
    }
    return cudaSuccess;
}

