cudaError_t cudaGetDeviceCount(int *count) {
    API_LOCK();
    if (count == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    cudaError_t error = initialize();
    *count = error == cudaSuccess ? static_cast<int>(g_devices.size()) : 0;
    return recordError(error);
}

cudaError_t cudaSetDevice(int device) {
    API_LOCK();
    RT_CHECK(initialize());
    if (device < 0 || device >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    t_device = device;
    return activateDevice(device);
}

cudaError_t cudaInitDevice(int device, unsigned int, unsigned int) {
    API_LOCK();
    return activateDevice(device);
}

cudaError_t cudaGetDevice(int *device) {
    API_LOCK();
    if (device == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(initialize());
    *device = t_device;
    return cudaSuccess;
}

cudaError_t cudaSetDeviceFlags(unsigned int) {
    return cudaSuccess;
}

cudaError_t cudaGetDeviceFlags(unsigned int *flags) {
    if (flags != nullptr) {
        *flags = 0;
    }
    return cudaSuccess;
}

cudaError_t cudaChooseDevice(int *device, const struct cudaDeviceProp *) {
    if (device == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *device = 0;
    return cudaSuccess;
}

cudaError_t cudaDeviceGetAttribute(int *value, enum cudaDeviceAttr attr, int device) {
    API_LOCK();
    if (value == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    int previous = t_device;
    RT_CHECK(activateDevice(device));
    // the runtime attribute numbering is the same as the driver's
    if (libreCuDeviceGetAttribute(value, static_cast<LibreCuDeviceAttribute>(attr), g_devices[device].device) != 0) {
        // attribute not known to LibreCUDA: report the feature as unsupported
        *value = 0;
    }
    activateDevice(previous);
    return cudaSuccess;
}

static int deviceAttribute(int device, LibreCuDeviceAttribute attr) {
    int value = 0;
    libreCuDeviceGetAttribute(&value, attr, g_devices[device].device);
    return value;
}

cudaError_t cudaGetDeviceProperties(struct cudaDeviceProp *prop, int device) {
    API_LOCK();
    if (prop == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    int previous = t_device;
    RT_CHECK(activateDevice(device));
    LibreCUdevice dev = g_devices[device].device;
    memset(prop, 0, sizeof(*prop));
    libreCuDeviceGetName(prop->name, sizeof(prop->name), dev);
    libreCuDeviceGetUuid(reinterpret_cast<uint8_t *>(prop->uuid.bytes), dev);
    size_t total_mem{};
    libreCuDeviceTotalMem(&total_mem, dev);
    prop->totalGlobalMem = total_mem;
    prop->sharedMemPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK);
    prop->regsPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_REGISTERS_PER_BLOCK);
    prop->warpSize = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_WARP_SIZE);
    prop->memPitch = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_PITCH);
    prop->maxThreadsPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_BLOCK);
    prop->maxThreadsDim[0] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCK_DIM_X);
    prop->maxThreadsDim[1] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCK_DIM_Y);
    prop->maxThreadsDim[2] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCK_DIM_Z);
    prop->maxGridSize[0] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_GRID_DIM_X);
    prop->maxGridSize[1] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_GRID_DIM_Y);
    prop->maxGridSize[2] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_GRID_DIM_Z);
    prop->totalConstMem = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_TOTAL_CONSTANT_MEMORY);
    prop->major = g_devices[device].ccMajor;
    prop->minor = g_devices[device].ccMinor;
    prop->textureAlignment = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_TEXTURE_ALIGNMENT);
    prop->texturePitchAlignment = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_TEXTURE_PITCH_ALIGNMENT);
    prop->multiProcessorCount = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT);
    prop->integrated = 0;
    prop->canMapHostMemory = 1;
    prop->surfaceAlignment = 512;
    prop->concurrentKernels = 1;
    prop->cooperativeLaunch = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_COOPERATIVE_LAUNCH);
    prop->pciBusID = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_BUS_ID);
    prop->pciDeviceID = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DEVICE_ID);
    prop->pciDomainID = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DOMAIN_ID);
    prop->asyncEngineCount = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_ASYNC_ENGINE_COUNT);
    prop->unifiedAddressing = 1;
    prop->managedMemory = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MANAGED_MEMORY);
    prop->concurrentManagedAccess = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_CONCURRENT_MANAGED_ACCESS);
    prop->memoryBusWidth = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_GLOBAL_MEMORY_BUS_WIDTH);
    prop->l2CacheSize = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_L2_CACHE_SIZE);
    prop->maxThreadsPerMultiProcessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_MULTIPROCESSOR);
    prop->globalL1CacheSupported = 1;
    prop->localL1CacheSupported = 1;
    prop->sharedMemPerMultiprocessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_MULTIPROCESSOR);
    prop->regsPerMultiprocessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_REGISTERS_PER_MULTIPROCESSOR);
    prop->computePreemptionSupported = 1;
    prop->sharedMemPerBlockOptin = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN);
    prop->maxBlocksPerMultiProcessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCKS_PER_MULTIPROCESSOR);
    prop->reservedSharedMemPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_RESERVED_SHARED_MEMORY_PER_BLOCK);
    prop->deviceNumaId = -1;
    prop->hostNumaId = -1;
    activateDevice(previous);
    return cudaSuccess;
}

cudaError_t cudaDeviceGetPCIBusId(char *pciBusId, int len, int device) {
    API_LOCK();
    RT_CHECK(activateDevice(device));
    snprintf(pciBusId, len, "%08X:%02X:%02X.0", deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DOMAIN_ID),
             deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_BUS_ID),
             deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DEVICE_ID));
    activateCurrentDevice();
    return cudaSuccess;
}

cudaError_t cudaDeviceSynchronize(void) {
    API_LOCK();
    RT_CHECK(prohibitedDuringCapture());
    RT_CHECK(activateCurrentDevice());
    return synchronizeDevice(t_device);
}

cudaError_t cudaDeviceReset(void) {
    API_LOCK();
    if (!g_initialized || g_initError != cudaSuccess) {
        return cudaSuccess;
    }
    return resetDevice(t_device);
}

cudaError_t cudaThreadSynchronize(void) {
    return cudaDeviceSynchronize();
}

cudaError_t cudaDeviceSetLimit(enum cudaLimit limit, size_t value) {
    API_LOCK();
    RT_CHECK(activateCurrentDevice());
    if (limit == cudaLimitStackSize) {
        LC_CHECK(libreCuCtxSetStackLimit(value));
    } else if (limit == cudaLimitPrintfFifoSize) {
        LC_CHECK(libreCuCtxSetPrintfFifoSize(value));
    } else if (limit == cudaLimitMallocHeapSize) {
        LC_CHECK(libreCuCtxSetMallocHeapSize(value));
    } else if (limit == cudaLimitDevRuntimePendingLaunchCount) {
        if (value > UINT32_MAX) {
            return recordError(cudaErrorInvalidValue);
        }
        LC_CHECK(libreCuCtxSetDeviceLaunchQueueSize(static_cast<uint32_t>(value)));
    }
    return cudaSuccess;
}

cudaError_t cudaDeviceGetLimit(size_t *pValue, enum cudaLimit limit) {
    API_LOCK();
    if (pValue == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    switch (limit) {
        case cudaLimitStackSize:
            LC_CHECK(libreCuCtxGetStackLimit(pValue));
            break;
        case cudaLimitPrintfFifoSize:
            LC_CHECK(libreCuCtxGetPrintfFifoSize(pValue));
            break;
        case cudaLimitMallocHeapSize:
            LC_CHECK(libreCuCtxGetMallocHeapSize(pValue));
            break;
        case cudaLimitDevRuntimePendingLaunchCount: {
            uint32_t launches{};
            LC_CHECK(libreCuCtxGetDeviceLaunchQueueSize(&launches));
            *pValue = launches;
            break;
        }
        case cudaLimitDevRuntimeSyncDepth:
            // device side synchronization doesn't exist since CUDA 12; the nesting depth of launches is 24
            *pValue = 2;
            break;
        default:
            *pValue = 0;
            break;
    }
    return cudaSuccess;
}

cudaError_t cudaDeviceSetCacheConfig(enum cudaFuncCache) {
    return cudaSuccess;
}

cudaError_t cudaDeviceGetCacheConfig(enum cudaFuncCache *pCacheConfig) {
    if (pCacheConfig != nullptr) {
        *pCacheConfig = cudaFuncCachePreferNone;
    }
    return cudaSuccess;
}

