static cudaError_t p2pCapabilities(int device, int peer, bool *pRead, bool *pWrite, bool *pAtomics) {
    RT_CHECK(initialize());
    if (device < 0 || device >= static_cast<int>(g_devices.size()) || peer < 0 ||
        peer >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    LC_CHECK(libreCuDeviceGetP2PCapabilities(g_devices[device].device, g_devices[peer].device, pRead, pWrite,
                                             pAtomics));
    return cudaSuccess;
}

cudaError_t cudaDeviceCanAccessPeer(int *canAccessPeer, int device, int peerDevice) {
    API_LOCK();
    if (canAccessPeer == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    bool read{}, write{}, atomics{};
    RT_CHECK(p2pCapabilities(device, peerDevice, &read, &write, &atomics));
    *canAccessPeer = device != peerDevice && read && write;
    return cudaSuccess;
}

cudaError_t cudaDeviceGetP2PAttribute(int *value, enum cudaDeviceP2PAttr attr, int srcDevice, int dstDevice) {
    API_LOCK();
    if (value == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    bool read{}, write{}, atomics{};
    RT_CHECK(p2pCapabilities(srcDevice, dstDevice, &read, &write, &atomics));
    if (srcDevice == dstDevice) {
        return recordError(cudaErrorInvalidDevice);
    }
    switch (attr) {
        case cudaDevP2PAttrPerformanceRank:
        case cudaDevP2PAttrOnlyPartialNativeAtomicSupported:
            *value = 0;
            break;
        case cudaDevP2PAttrAccessSupported:
        case cudaDevP2PAttrCudaArrayAccessSupported:
            *value = read && write;
            break;
        case cudaDevP2PAttrNativeAtomicSupported:
            *value = read && write && atomics;
            break;
        default:
            return recordError(cudaErrorInvalidValue);
    }
    return cudaSuccess;
}

/**
 * Gives the current device's GPU access to the memory of peerDevice: the peer's allocations (existing and future)
 * are mapped on it at the same addresses
 */
cudaError_t cudaDeviceEnablePeerAccess(int peerDevice, unsigned int flags) {
    API_LOCK();
    RT_CHECK(initialize());
    if (peerDevice < 0 || peerDevice >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    if (peerDevice == t_device) {
        return recordError(cudaErrorPeerAccessUnsupported);
    }
    if (flags != 0) {
        return recordError(cudaErrorInvalidValue);
    }
    const int device = t_device;
    RT_CHECK(activateDevice(peerDevice));
    RT_CHECK(activateDevice(device));
    LC_CHECK(libreCuCtxEnablePeerAccess(g_devices[peerDevice].ctx, 0));
    return cudaSuccess;
}

cudaError_t cudaDeviceDisablePeerAccess(int peerDevice) {
    API_LOCK();
    RT_CHECK(initialize());
    if (peerDevice < 0 || peerDevice >= static_cast<int>(g_devices.size()) || peerDevice == t_device) {
        return recordError(cudaErrorInvalidDevice);
    }
    RT_CHECK(activateCurrentDevice());
    if (g_devices[peerDevice].ctx == nullptr) {
        return recordError(cudaErrorPeerAccessNotEnabled);
    }
    LC_CHECK(libreCuCtxDisablePeerAccess(g_devices[peerDevice].ctx));
    return cudaSuccess;
}

// ---------------------------------------------------------------------------------------------------------------------
// memory

cudaError_t cudaMalloc(void **devPtr, size_t size) {
    API_SHARED_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (devPtr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    if (size == 0) {
        *devPtr = nullptr;
        return cudaSuccess;
    }
    LC_CHECK(libreCuMemAlloc(devPtr, size, false));
    return cudaSuccess;
}

cudaError_t cudaFree(void *devPtr) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    RT_CHECK(activateCurrentDevice());
    if (devPtr == nullptr) {
        return cudaSuccess;
    }
    if (isGraphAllocation(devPtr)) {
        // graph memory stays with its graph (the next launch uses it again)
        return cudaSuccess;
    }
    // memory may still be in use by queued work (of its device or, with peer access, the current one)
    RT_CHECK(synchronizeDevice(t_device));
    const int owner = ownerDevice(devPtr);
    if (owner >= 0 && owner != t_device) {
        RT_CHECK(synchronizeDevice(owner));
    }
    LC_CHECK(libreCuMemFree(devPtr));
    return cudaSuccess;
}

cudaError_t cudaMallocAsync(void **devPtr, size_t size, cudaStream_t handle) {
    {
        API_LOCK();
        CUstream_st *stream{};
        RT_CHECK(resolveStream(handle, &stream));
        if (capturing(stream)) {
            // a memory allocation node
            return captureMallocAsync(stream, devPtr, size);
        }
    }
    return cudaMalloc(devPtr, size);
}

cudaError_t cudaFreeAsync(void *devPtr, cudaStream_t handle) {
    {
        API_LOCK();
        CUstream_st *stream{};
        RT_CHECK(resolveStream(handle, &stream));
        if (capturing(stream)) {
            // a memory free node
            return captureFreeAsync(stream, devPtr);
        }
    }
    return cudaFree(devPtr);
}

cudaError_t cudaMallocPitch(void **devPtr, size_t *pitch, size_t width, size_t height) {
    if (pitch == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *pitch = (width + 511) & ~size_t(511);
    return cudaMalloc(devPtr, *pitch * height);
}

/**
 * UVM managed memory: pages migrate between system memory and the GPUs on access. LIBRECUDA_MANAGED_BAR1=1 selects
 * device memory mapped into the CPU address space through BAR1 instead. The attach flags make no difference (all
 * memory is accessible from any stream).
 */
cudaError_t cudaMallocManaged(void **devPtr, size_t size, unsigned int flags) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (devPtr == nullptr || size == 0 || (flags != cudaMemAttachGlobal && flags != cudaMemAttachHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    LC_CHECK(libreCuMemAllocManaged(devPtr, size));
    return cudaSuccess;
}

static cudaError_t managedLocation(const cudaMemLocation &location, bool allowNone, LibreCUdevice *pDevice) {
    switch (location.type) {
        case cudaMemLocationTypeDevice:
            if (location.id < 0 || location.id >= static_cast<int>(g_devices.size())) {
                return recordError(cudaErrorInvalidDevice);
            }
            *pDevice = g_devices[location.id].device;
            return cudaSuccess;
        case cudaMemLocationTypeHost:
        case cudaMemLocationTypeHostNuma:
        case cudaMemLocationTypeHostNumaCurrent:
            *pDevice = nullptr;
            return cudaSuccess;
        case cudaMemLocationTypeNone:
            if (allowNone) {
                *pDevice = nullptr;
                return cudaSuccess;
            }
            [[fallthrough]];
        default:
            return recordError(cudaErrorInvalidValue);
    }
}

/**
 * Migrates managed memory once the stream's preceding work completed; returns when the migration is done
 */
cudaError_t cudaMemPrefetchAsync(const void *devPtr, size_t count, struct cudaMemLocation location,
                                 unsigned int flags, cudaStream_t handle) {
    API_LOCK();
    RT_CHECK(initialize());
    if (devPtr == nullptr || count == 0 || flags != 0 || !libreCuMemIsManaged(devPtr)) {
        return recordError(cudaErrorInvalidValue);
    }
    LibreCUdevice device{};
    RT_CHECK(managedLocation(location, false, &device));
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (capturing(stream)) {
        return captureUnsupported(stream);
    }
    RT_CHECK(synchronizeStream(stream));
    LC_CHECK(blocking([&] { return libreCuMemPrefetch(devPtr, count, device); }));
    return cudaSuccess;
}

cudaError_t cudaMemAdvise(const void *devPtr, size_t count, enum cudaMemoryAdvise advice,
                          struct cudaMemLocation location) {
    API_LOCK();
    RT_CHECK(initialize());
    if (devPtr == nullptr || count == 0 || !libreCuMemIsManaged(devPtr) || advice < cudaMemAdviseSetReadMostly ||
        advice > cudaMemAdviseUnsetAccessedBy) {
        return recordError(cudaErrorInvalidValue);
    }
    LibreCUdevice device{};
    // read mostly and unsetting the preferred location ignore the location
    const bool needs_location = advice != cudaMemAdviseSetReadMostly && advice != cudaMemAdviseUnsetReadMostly &&
                                advice != cudaMemAdviseUnsetPreferredLocation;
    RT_CHECK(managedLocation(location, !needs_location, &device));
    LC_CHECK(libreCuMemAdvise(devPtr, count, static_cast<LibreCuMemAdvice>(advice), device));
    return cudaSuccess;
}

cudaError_t cudaMallocHost(void **ptr, size_t size) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (ptr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    if (size == 0) {
        *ptr = nullptr;
        return cudaSuccess;
    }
    LC_CHECK(libreCuMemAllocHost(ptr, size));
    return cudaSuccess;
}

cudaError_t cudaHostAlloc(void **pHost, size_t size, unsigned int) {
    return cudaMallocHost(pHost, size);
}

cudaError_t cudaFreeHost(void *ptr) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (ptr == nullptr) {
        return cudaSuccess;
    }
    RT_CHECK(activateCurrentDevice());
    // page-locked memory is usable from every device
    for (size_t device = 0; device < g_devices.size(); device++) {
        RT_CHECK(synchronizeDevice(static_cast<int>(device)));
    }
    LC_CHECK(libreCuMemFreeHost(ptr));
    return cudaSuccess;
}

cudaError_t cudaHostGetDevicePointer(void **pDevice, void *pHost, unsigned int) {
    API_LOCK();
    if (pDevice == nullptr || !libreCuMemIsPinnedHost(pHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    // pinned host memory is mapped at the same address on the GPU
    *pDevice = pHost;
    return cudaSuccess;
}

cudaError_t cudaHostGetFlags(unsigned int *pFlags, void *pHost) {
    if (pFlags == nullptr || !libreCuMemIsPinnedHost(pHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    *pFlags = cudaHostAllocMapped;
    return cudaSuccess;
}

cudaError_t cudaHostRegister(void *, size_t, unsigned int) {
    // registration is not needed for correctness: copies from unregistered memory are staged
    return cudaSuccess;
}

cudaError_t cudaHostUnregister(void *) {
    return cudaSuccess;
}

cudaError_t cudaMemGetInfo(size_t *free, size_t *total) {
    API_LOCK();
    RT_CHECK(activateCurrentDevice());
    LC_CHECK(libreCuMemGetInfo(free, total));
    return cudaSuccess;
}

cudaError_t cudaPointerGetAttributes(struct cudaPointerAttributes *attributes, const void *ptr) {
    API_LOCK();
    if (attributes == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    memset(attributes, 0, sizeof(*attributes));
    attributes->device = std::max(ownerDevice(ptr), 0);
    switch (classify(ptr)) {
        case PtrKind::DEVICE:
            // BAR1 managed memory is device memory the CPU can access too
            attributes->type = libreCuMemIsManaged(ptr) ? cudaMemoryTypeManaged : cudaMemoryTypeDevice;
            attributes->devicePointer = const_cast<void *>(ptr);
            if (attributes->type == cudaMemoryTypeManaged) {
                attributes->hostPointer = const_cast<void *>(ptr);
            }
            break;
        case PtrKind::MANAGED:
            attributes->type = cudaMemoryTypeManaged;
            attributes->devicePointer = const_cast<void *>(ptr);
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
        case PtrKind::PINNED:
            attributes->type = cudaMemoryTypeHost;
            attributes->devicePointer = const_cast<void *>(ptr);
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
        case PtrKind::PAGEABLE:
            attributes->type = cudaMemoryTypeUnregistered;
            attributes->device = -2;
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
    }
    return cudaSuccess;
}

cudaError_t cudaMemcpy(void *dst, const void *src, size_t count, enum cudaMemcpyKind) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    return memcpyOnStream(dst, src, count, stream, true);
}

cudaError_t cudaMemcpyAsync(void *dst, const void *src, size_t count, enum cudaMemcpyKind, cudaStream_t handle) {
    STREAM_OP_LOCK(handle);
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    return memcpyOnStream(dst, src, count, stream, false);
}

static bool validDevice(int device) {
    return device >= 0 && device < static_cast<int>(g_devices.size());
}

// the devices of the pointers follow from their addresses (unified addressing)
cudaError_t cudaMemcpyPeer(void *dst, int dstDevice, const void *src, int srcDevice, size_t count) {
    API_LOCK();
    RT_CHECK(initialize());
    if (!validDevice(dstDevice) || !validDevice(srcDevice)) {
        return recordError(cudaErrorInvalidDevice);
    }
    return cudaMemcpy(dst, src, count, cudaMemcpyDefault);
}

cudaError_t cudaMemcpyPeerAsync(void *dst, int dstDevice, const void *src, int srcDevice, size_t count,
                                cudaStream_t stream) {
    {
        API_LOCK();
        RT_CHECK(initialize());
        if (!validDevice(dstDevice) || !validDevice(srcDevice)) {
            return recordError(cudaErrorInvalidDevice);
        }
    }
    return cudaMemcpyAsync(dst, src, count, cudaMemcpyDefault, stream);
}

static cudaError_t memcpy2D(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                            cudaStream_t handle, bool synchronous) {
    API_LOCK();
    if (width > dpitch || width > spitch) {
        return recordError(cudaErrorInvalidPitchValue);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (capturing(stream)) {
        if (synchronous || classify(dst) == PtrKind::PAGEABLE || classify(src) == PtrKind::PAGEABLE) {
            return captureUnsupported(stream);
        }
        cudaMemcpy3DParms p{};
        p.dstPtr = cudaPitchedPtr{dst, dpitch, width, height};
        p.srcPtr = cudaPitchedPtr{const_cast<void *>(src), spitch, width, height};
        p.extent = cudaExtent{width, height, 1};
        p.kind = cudaMemcpyDefault;
        return captureCopy(stream, p);
    }
    if (dpitch == width && spitch == width) {
        return memcpyOnStream(dst, src, width * height, stream, synchronous);
    }
    for (size_t row = 0; row < height; row++) {
        RT_CHECK(memcpyOnStream(static_cast<uint8_t *>(dst) + row * dpitch,
                                static_cast<const uint8_t *>(src) + row * spitch, width, stream, false));
    }
    if (synchronous) {
        RT_CHECK(synchronizeStream(stream));
    }
    return cudaSuccess;
}

cudaError_t cudaMemcpy2D(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                         enum cudaMemcpyKind) {
    return memcpy2D(dst, dpitch, src, spitch, width, height, nullptr, true);
}

cudaError_t cudaMemcpy2DAsync(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                              enum cudaMemcpyKind, cudaStream_t stream) {
    return memcpy2D(dst, dpitch, src, spitch, width, height, stream, false);
}

cudaError_t cudaMemset(void *devPtr, int value, size_t count) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    // like CUDA, memset on device memory is asynchronous with respect to the host
    return memsetOnStream(devPtr, value, count, stream, false);
}

cudaError_t cudaMemsetAsync(void *devPtr, int value, size_t count, cudaStream_t handle) {
    STREAM_OP_LOCK(handle);
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    return memsetOnStream(devPtr, value, count, stream, false);
}

// ---------------------------------------------------------------------------------------------------------------------
// CUDA arrays

namespace {
cudaError_t textureFormat(const cudaChannelFormatDesc &desc, cudaTextureReadMode readMode, LibreCuTexFormat *pFormat,
                          uint32_t *pChannels, uint32_t *pBits);

/**
 * One side of an array copy: an array with the origin in texels (z: slice or layer), or memory with the region's
 * start, the bytes between rows and between slices
 */
struct CopySide {
    cudaArray *array;
    size_t x, y, z;
    void *ptr;
    size_t pitch, slicePitch;
};

LibreCuMemcpy3DSide driverSide(const CopySide &side, void *ptr) {
    LibreCuMemcpy3DSide d{};
    if (side.array != nullptr) {
        d.array = side.array->array;
        d.x = static_cast<uint32_t>(side.x);
        d.y = static_cast<uint32_t>(side.y);
        d.z = static_cast<uint32_t>(side.z);
    } else {
        d.ptr = ptr;
        d.pitch = side.pitch;
        d.slicePitch = side.slicePitch;
    }
    return d;
}

/**
 * Copies widthBytes x height x depth from src to dst where at least one side is an array. Memory the GPU can't
 * access (pageable host memory) goes through a temporary device buffer; such copies complete before returning.
 */
cudaError_t arrayCopy(const CopySide &dst, const CopySide &src, size_t widthBytes, size_t height, size_t depth,
                      cudaStream_t handle, bool synchronous) {
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (widthBytes == 0 || height == 0 || depth == 0) {
        return cudaSuccess;
    }
    const bool host_src = src.array == nullptr && !libreCuMemIsDevice(src.ptr) && !libreCuMemIsPinnedHost(src.ptr);
    const bool host_dst = dst.array == nullptr && !libreCuMemIsDevice(dst.ptr) && !libreCuMemIsPinnedHost(dst.ptr);
    // another device's arrays or memory (without peer access) aren't supported
    for (const CopySide *side: {&src, &dst}) {
        if (side->array != nullptr ? side->array->device != stream->device
                                   : libreCuMemIsDevice(side->ptr) && !accessibleFrom(side->ptr, stream)) {
            return recordError(cudaErrorInvalidValue);
        }
    }
    if (capturing(stream)) {
        if (synchronous || host_src || host_dst) {
            return captureUnsupported(stream);
        }
        // as cudaMemcpy3D parameters: arrays with positions and the width in elements
        cudaArray *array = src.array != nullptr ? src.array : dst.array;
        cudaMemcpy3DParms p{};
        auto side = [&](const CopySide &c, cudaArray **pArray, cudaPos *pPos, cudaPitchedPtr *pPtr) {
            if (c.array != nullptr) {
                *pArray = c.array;
                *pPos = cudaPos{c.x, c.y, c.z};
            } else {
                *pPtr = cudaPitchedPtr{c.ptr, c.pitch, widthBytes, c.pitch != 0 ? c.slicePitch / c.pitch : 0};
            }
        };
        side(src, &p.srcArray, &p.srcPos, &p.srcPtr);
        side(dst, &p.dstArray, &p.dstPos, &p.dstPtr);
        p.extent = cudaExtent{widthBytes / array->elementSize, height, depth};
        p.kind = cudaMemcpyDefault;
        return captureCopy(stream, p);
    }
    RT_CHECK(beginOperation(stream));
    if (!host_src && !host_dst) {
        const LibreCuMemcpy3DSide d = driverSide(dst, dst.ptr), s = driverSide(src, src.ptr);
        LC_CHECK(libreCuMemcpy3D(&d, &s, widthBytes, height, depth, stream->stream, true));
        RT_CHECK(endOperation(stream));
        if (synchronous) {
            RT_CHECK(synchronizeStream(stream));
        }
        return cudaSuccess;
    }
    // pageable host memory: packed into a temporary device buffer (rows widthBytes apart)
    const size_t bytes = widthBytes * height * depth;
    void *staging{};
    LC_CHECK(libreCuMemAlloc(&staging, bytes, false));
    std::vector<uint8_t> packed(bytes);
    CopySide packed_side{.ptr = staging, .pitch = widthBytes, .slicePitch = widthBytes * height};
    const CopySide &host = host_src ? src : dst;
    auto host_row = [&](size_t z, size_t y) { return static_cast<uint8_t *>(host.ptr) + z * host.slicePitch + y * host.pitch; };
    cudaError_t error = cudaSuccess;
    if (host_src) {
        if (libreCuMemIsManaged(src.ptr)) {
            // the CPU reads managed memory the stream's preceding work may write
            error = synchronizeStream(stream);
        }
        for (size_t z = 0; error == cudaSuccess && z < depth; z++) {
            for (size_t y = 0; y < height; y++) {
                memcpy(packed.data() + (z * height + y) * widthBytes, host_row(z, y), widthBytes);
            }
        }
        error = memcpyOnStream(staging, packed.data(), bytes, stream, false);
        if (error == cudaSuccess) {
            const LibreCuMemcpy3DSide d = driverSide(dst, dst.ptr), s = driverSide(packed_side, staging);
            const libreCudaStatus_t status = libreCuMemcpy3D(&d, &s, widthBytes, height, depth, stream->stream, true);
            error = status == 0 ? cudaSuccess : recordError(mapStatus(status));
        }
    } else {
        const LibreCuMemcpy3DSide d = driverSide(packed_side, staging), s = driverSide(src, src.ptr);
        const libreCudaStatus_t status = libreCuMemcpy3D(&d, &s, widthBytes, height, depth, stream->stream, true);
        error = status == 0 ? cudaSuccess : recordError(mapStatus(status));
        if (error == cudaSuccess) {
            error = memcpyOnStream(packed.data(), staging, bytes, stream, false);
        }
        if (error == cudaSuccess) {
            for (size_t z = 0; z < depth; z++) {
                for (size_t y = 0; y < height; y++) {
                    memcpy(host_row(z, y), packed.data() + (z * height + y) * widthBytes, widthBytes);
                }
            }
        }
    }
    if (error == cudaSuccess) {
        error = endOperation(stream);
    }
    // the staging buffer may only be freed once the copies completed
    const cudaError_t sync_error = synchronizeStream(stream);
    libreCuMemFree(staging);
    return error != cudaSuccess ? error : sync_error;
}

cudaError_t mallocArray(cudaArray_t *pArray, const cudaChannelFormatDesc *desc, cudaExtent extent,
                        unsigned int flags) {
    if (pArray == nullptr || desc == nullptr || extent.width == 0) {
        return recordError(cudaErrorInvalidValue);
    }
    if (extent.width > UINT32_MAX || extent.height > UINT32_MAX || extent.depth > UINT32_MAX) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    LibreCuTexFormat format{};
    uint32_t channels{}, bits{};
    RT_CHECK(textureFormat(*desc, cudaReadModeElementType, &format, &channels, &bits));
    const uint32_t array_flags = ((flags & cudaArrayLayered) ? LIBRECUDA_ARRAY_LAYERED : 0) |
                                 ((flags & cudaArrayCubemap) ? LIBRECUDA_ARRAY_CUBEMAP : 0);
    LibreCUarray array{};
    LC_CHECK(libreCuArrayCreate(&array, static_cast<uint32_t>(extent.width), static_cast<uint32_t>(extent.height),
                                static_cast<uint32_t>(extent.depth), array_flags, format, channels, bits));
    *pArray = new cudaArray{.device = t_device, .array = array, .desc = *desc, .extent = extent, .flags = flags,
                            .elementSize = size_t(channels) * bits / 8};
    g_devices[t_device].arrays.insert(*pArray);
    return cudaSuccess;
}

// rows and slices (or layers) of an array, at least 1
size_t arrayHeight(const cudaArray *array) {
    return std::max<size_t>(1, array->extent.height);
}

size_t arrayDepth(const cudaArray *array) {
    return std::max<size_t>(1, array->extent.depth);
}

/**
 * Copies count bytes between an array (from byte offset wOffset in row hOffset on, row by row) and memory
 */
cudaError_t arrayLinearCopy(cudaArray *array, size_t wOffset, size_t hOffset, void *ptr, size_t count,
                            bool toArray, cudaStream_t stream, bool synchronous) {
    if (array == nullptr || ptr == nullptr || wOffset % array->elementSize != 0) {
        return recordError(cudaErrorInvalidValue);
    }
    const size_t row_bytes = array->extent.width * array->elementSize;
    size_t x = wOffset, y = hOffset, done = 0;
    while (done < count) {
        if (y >= arrayHeight(array) || x >= row_bytes) {
            return recordError(cudaErrorInvalidValue);
        }
        // the rest of the row, or as many whole rows as fit
        size_t width = std::min(count - done, row_bytes - x), rows = 1;
        if (x == 0 && width == row_bytes) {
            rows = std::min((count - done) / row_bytes, arrayHeight(array) - y);
        }
        CopySide array_side{.array = array, .x = x / array->elementSize, .y = y};
        CopySide memory{.ptr = static_cast<uint8_t *>(ptr) + done, .pitch = width};
        RT_CHECK(toArray ? arrayCopy(array_side, memory, width, rows, 1, stream, false)
                         : arrayCopy(memory, array_side, width, rows, 1, stream, false));
        done += width * rows;
        x += width;
        if (x == row_bytes) {
            x = 0;
            y += rows;
        }
    }
    if (synchronous) {
        CUstream_st *resolved{};
        RT_CHECK(resolveStream(stream, &resolved));
        RT_CHECK(synchronizeStream(resolved));
    }
    return cudaSuccess;
}

/**
 * cudaMemcpy3D: pitched memory and / or arrays
 */
cudaError_t memcpy3D(const cudaMemcpy3DParms *p, cudaStream_t stream, bool synchronous) {
    if (p == nullptr || (p->srcArray != nullptr && p->srcPtr.ptr != nullptr) ||
        (p->dstArray != nullptr && p->dstPtr.ptr != nullptr)) {
        return recordError(cudaErrorInvalidValue);
    }
    CUstream_st *resolved_stream{};
    RT_CHECK(resolveStream(stream, &resolved_stream));
    if (capturing(resolved_stream)) {
        const bool pageable = (p->srcArray == nullptr && classify(p->srcPtr.ptr) == PtrKind::PAGEABLE) ||
                              (p->dstArray == nullptr && classify(p->dstPtr.ptr) == PtrKind::PAGEABLE);
        return synchronous || pageable ? captureUnsupported(resolved_stream) : captureCopy(resolved_stream, *p);
    }
    const cudaExtent &e = p->extent;
    // with an array involved, x positions and the width are in elements (bytes for memory)
    cudaArray *array = p->srcArray != nullptr ? p->srcArray : p->dstArray;
    const size_t element_size = array != nullptr ? array->elementSize : 1;
    const size_t width_bytes = e.width * element_size;
    auto side = [&](cudaArray *a, const cudaPos &pos, const cudaPitchedPtr &ptr) {
        CopySide s{};
        if (a != nullptr) {
            s.array = a;
            s.x = pos.x;
            s.y = pos.y;
            s.z = pos.z;
        } else {
            const size_t slice = ptr.pitch * ptr.ysize;
            s.ptr = static_cast<uint8_t *>(ptr.ptr) + pos.z * slice + pos.y * ptr.pitch + pos.x * element_size;
            s.pitch = ptr.pitch;
            s.slicePitch = slice;
        }
        return s;
    };
    const CopySide dst = side(p->dstArray, p->dstPos, p->dstPtr), src = side(p->srcArray, p->srcPos, p->srcPtr);
    if (array != nullptr) {
        return arrayCopy(dst, src, width_bytes, e.height, e.depth, stream, synchronous);
    }
    // pitched memory only: slice by slice
    for (size_t z = 0; z < e.depth; z++) {
        RT_CHECK(memcpy2D(static_cast<uint8_t *>(dst.ptr) + z * dst.slicePitch, dst.pitch,
                          static_cast<uint8_t *>(src.ptr) + z * src.slicePitch, src.pitch, width_bytes, e.height,
                          stream, false));
    }
    if (synchronous) {
        CUstream_st *resolved{};
        RT_CHECK(resolveStream(stream, &resolved));
        RT_CHECK(synchronizeStream(resolved));
    }
    return cudaSuccess;
}
} // namespace

cudaError_t cudaMallocArray(cudaArray_t *array, const struct cudaChannelFormatDesc *desc, size_t width, size_t height,
                            unsigned int flags) {
    API_LOCK();
    cudaExtent extent{};
    extent.width = width;
    extent.height = height;
    return mallocArray(array, desc, extent, flags);
}

cudaError_t cudaMalloc3DArray(cudaArray_t *array, const struct cudaChannelFormatDesc *desc, struct cudaExtent extent,
                              unsigned int flags) {
    API_LOCK();
    // layered arrays need layers (depth); 1D layered arrays have height 0
    if ((flags & cudaArrayLayered) && extent.depth == 0) {
        return recordError(cudaErrorInvalidValue);
    }
    return mallocArray(array, desc, extent, flags);
}

cudaError_t cudaFreeArray(cudaArray_t array) {
    API_LOCK();
    if (array == nullptr) {
        return cudaSuccess;
    }
    if (array->isLevel) {
        return recordError(cudaErrorInvalidValue); // freed with its mipmapped array
    }
    if (array->array == nullptr) {
        // freed by cudaDeviceReset
        delete array;
        return cudaSuccess;
    }
    RT_CHECK(activateDevice(array->device));
    // work using the array may still be queued
    RT_CHECK(synchronizeDevice(array->device));
    g_devices[array->device].arrays.erase(array);
    LC_CHECK(libreCuArrayDestroy(array->array));
    delete array;
    return cudaSuccess;
}

cudaError_t cudaMallocMipmappedArray(cudaMipmappedArray_t *mipmappedArray, const struct cudaChannelFormatDesc *desc,
                                     struct cudaExtent extent, unsigned int numLevels, unsigned int flags) {
    API_LOCK();
    if (mipmappedArray == nullptr || desc == nullptr || extent.width == 0 || numLevels == 0 ||
        extent.width > UINT32_MAX || extent.height > UINT32_MAX || extent.depth > UINT32_MAX) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    LibreCuTexFormat format{};
    uint32_t channels{}, bits{};
    RT_CHECK(textureFormat(*desc, cudaReadModeElementType, &format, &channels, &bits));
    const uint32_t array_flags = ((flags & cudaArrayLayered) ? LIBRECUDA_ARRAY_LAYERED : 0) |
                                 ((flags & cudaArrayCubemap) ? LIBRECUDA_ARRAY_CUBEMAP : 0);
    LibreCUarray array{};
    LC_CHECK(libreCuMipmappedArrayCreate(&array, static_cast<uint32_t>(extent.width),
                                         static_cast<uint32_t>(extent.height), static_cast<uint32_t>(extent.depth),
                                         array_flags, numLevels, format, channels, bits));
    auto *mipmapped = new cudaMipmappedArray{};
    mipmapped->all = cudaArray{.device = t_device, .array = array, .desc = *desc, .extent = extent, .flags = flags,
                               .elementSize = size_t(channels) * bits / 8};
    const bool layered = (flags & (cudaArrayLayered | cudaArrayCubemap)) != 0;
    for (unsigned int l = 0; l < numLevels; l++) {
        LibreCUarray level{};
        LC_CHECK(libreCuArrayGetLevel(&level, array, l));
        // layers aren't halved; dimensions the array doesn't have stay 0
        cudaExtent level_extent{};
        level_extent.width = std::max<size_t>(1, extent.width >> l);
        level_extent.height = extent.height == 0 ? 0 : std::max<size_t>(1, extent.height >> l);
        level_extent.depth = extent.depth == 0 ? 0 : (layered ? extent.depth : std::max<size_t>(1, extent.depth >> l));
        mipmapped->levels.push_back(new cudaArray{.device = t_device, .array = level, .desc = *desc,
                                                  .extent = level_extent, .flags = flags,
                                                  .elementSize = mipmapped->all.elementSize, .isLevel = true});
    }
    g_devices[t_device].mipmappedArrays.insert(mipmapped);
    *mipmappedArray = mipmapped;
    return cudaSuccess;
}

cudaError_t cudaGetMipmappedArrayLevel(cudaArray_t *levelArray, cudaMipmappedArray_const_t mipmappedArray,
                                       unsigned int level) {
    API_LOCK();
    if (levelArray == nullptr || mipmappedArray == nullptr || level >= mipmappedArray->levels.size()) {
        return recordError(cudaErrorInvalidValue);
    }
    *levelArray = mipmappedArray->levels[level];
    return cudaSuccess;
}

cudaError_t cudaFreeMipmappedArray(cudaMipmappedArray_t mipmappedArray) {
    API_LOCK();
    if (mipmappedArray == nullptr) {
        return cudaSuccess;
    }
    if (mipmappedArray->all.array != nullptr) {
        RT_CHECK(activateDevice(mipmappedArray->all.device));
        RT_CHECK(synchronizeDevice(mipmappedArray->all.device));
        g_devices[mipmappedArray->all.device].mipmappedArrays.erase(mipmappedArray);
        LC_CHECK(libreCuArrayDestroy(mipmappedArray->all.array));
    }
    for (cudaArray *level: mipmappedArray->levels) {
        delete level;
    }
    delete mipmappedArray;
    return cudaSuccess;
}

cudaError_t cudaArrayGetInfo(struct cudaChannelFormatDesc *desc, struct cudaExtent *extent, unsigned int *flags,
                             cudaArray_t array) {
    if (array == nullptr) {
        return recordError(cudaErrorInvalidResourceHandle);
    }
    if (desc != nullptr) {
        *desc = array->desc;
    }
    if (extent != nullptr) {
        *extent = array->extent;
    }
    if (flags != nullptr) {
        *flags = array->flags;
    }
    return cudaSuccess;
}

cudaError_t cudaGetChannelDesc(struct cudaChannelFormatDesc *desc, cudaArray_const_t array) {
    if (desc == nullptr || array == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *desc = array->desc;
    return cudaSuccess;
}

cudaError_t cudaMemcpy2DToArrayAsync(cudaArray_t dst, size_t wOffset, size_t hOffset, const void *src, size_t spitch,
                                     size_t width, size_t height, enum cudaMemcpyKind, cudaStream_t stream) {
    API_LOCK();
    if (dst == nullptr || wOffset % dst->elementSize != 0) {
        return recordError(cudaErrorInvalidValue);
    }
    const CopySide d{.array = dst, .x = wOffset / dst->elementSize, .y = hOffset};
    const CopySide s{.ptr = const_cast<void *>(src), .pitch = spitch};
    return arrayCopy(d, s, width, height, 1, stream, false);
}

cudaError_t cudaMemcpy2DToArray(cudaArray_t dst, size_t wOffset, size_t hOffset, const void *src, size_t spitch,
                                size_t width, size_t height, enum cudaMemcpyKind kind) {
    API_LOCK();
    RT_CHECK(cudaMemcpy2DToArrayAsync(dst, wOffset, hOffset, src, spitch, width, height, kind, nullptr));
    return cudaStreamSynchronize(nullptr);
}

cudaError_t cudaMemcpy2DFromArrayAsync(void *dst, size_t dpitch, cudaArray_const_t src, size_t wOffset,
                                       size_t hOffset, size_t width, size_t height, enum cudaMemcpyKind,
                                       cudaStream_t stream) {
    API_LOCK();
    if (src == nullptr || wOffset % src->elementSize != 0) {
        return recordError(cudaErrorInvalidValue);
    }
    const CopySide d{.ptr = dst, .pitch = dpitch};
    const CopySide s{.array = const_cast<cudaArray *>(src), .x = wOffset / src->elementSize, .y = hOffset};
    return arrayCopy(d, s, width, height, 1, stream, false);
}

cudaError_t cudaMemcpy2DFromArray(void *dst, size_t dpitch, cudaArray_const_t src, size_t wOffset, size_t hOffset,
                                  size_t width, size_t height, enum cudaMemcpyKind kind) {
    API_LOCK();
    RT_CHECK(cudaMemcpy2DFromArrayAsync(dst, dpitch, src, wOffset, hOffset, width, height, kind, nullptr));
    return cudaStreamSynchronize(nullptr);
}

cudaError_t cudaMemcpy2DArrayToArray(cudaArray_t dst, size_t wOffsetDst, size_t hOffsetDst, cudaArray_const_t src,
                                     size_t wOffsetSrc, size_t hOffsetSrc, size_t width, size_t height,
                                     enum cudaMemcpyKind) {
    API_LOCK();
    if (dst == nullptr || src == nullptr || wOffsetDst % dst->elementSize != 0 ||
        wOffsetSrc % src->elementSize != 0 || dst->elementSize != src->elementSize) {
        return recordError(cudaErrorInvalidValue);
    }
    const CopySide d{.array = dst, .x = wOffsetDst / dst->elementSize, .y = hOffsetDst};
    const CopySide s{.array = const_cast<cudaArray *>(src), .x = wOffsetSrc / src->elementSize, .y = hOffsetSrc};
    return arrayCopy(d, s, width, height, 1, nullptr, true);
}

cudaError_t cudaMemcpyToArray(cudaArray_t dst, size_t wOffset, size_t hOffset, const void *src, size_t count,
                              enum cudaMemcpyKind) {
    API_LOCK();
    return arrayLinearCopy(dst, wOffset, hOffset, const_cast<void *>(src), count, true, nullptr, true);
}

