// ---------------------------------------------------------------------------------------------------------------------
// graphs and stream capture
//
// A graph is a set of nodes (kernel launches, copies, fills, host functions, child graphs, event records / waits,
// memory allocations and frees, empty nodes) with dependencies. Instantiating a graph copies it (later changes to the
// graph don't affect the executable graph), orders the nodes topologically and splits them into lanes: chains of
// nodes each depending on the previous one. Launching it replays the nodes in that order through the same paths as
// the API calls they stand for, the first lane on the launch stream and the others on internal streams of the
// executable graph, so independent branches run concurrently. A dependency between lanes is an event recorded after
// the node and waited for by the dependent's lane; the lanes start after the launch stream's preceding work and the
// launch stream waits for all of them at the end.
//
// Memory allocation nodes allocate their memory when they are created (the address is part of the node's
// parameters) and keep it while a graph or executable graph refers to it; free nodes and cudaFree of such memory
// don't release it, so the next launch finds it at the same address. Like in CUDA, graphs with memory nodes can't be
// cloned or used as (cloned) child graphs, and only one executable graph of such a graph may exist at a time.
//
// Stream capture records work submitted to a capturing stream as nodes instead of running it: each stream taking part
// in a capture has a set of tail nodes, and a new node depends on them and becomes the stream's tail. Recording an
// event in a capturing stream makes it carry the stream's tails; another stream waiting for such an event joins the
// capture (fork) and the origin stream waiting for an event of a forked stream joins the branches again. Calls that
// can't be captured invalidate the capture like in CUDA: synchronizing a capturing stream, synchronous copies, legacy
// default stream work that would synchronize with a capturing stream (cudaErrorStreamCaptureImplicit), and
// "potentially unsafe" calls (cudaMalloc, cudaFree, cudaDeviceSynchronize, ...) while a global (or this thread's
// thread local) capture is active, unless cudaThreadExchangeStreamCaptureMode made the thread relaxed. Capture state
// is only changed while holding the API lock exclusively.

namespace {
std::atomic<unsigned long long> g_nextCaptureId{1};
std::unordered_set<CaptureState *> g_captures{};
thread_local cudaStreamCaptureMode t_captureMode = cudaStreamCaptureModeGlobal;

void rebuildArgPointers(CUgraphNode_st *node) {
    node->argPtrs.clear();
    for (size_t offset: node->argOffsets) {
        node->argPtrs.push_back(node->args.data() + offset);
    }
}

/**
 * Copies the arguments of a kernel launch into the node (sizes from the kernel's parameters on the device)
 */
cudaError_t setKernel(CUgraphNode_st *node, const void *func, dim3 grid, dim3 block, unsigned int sharedMem,
                      void **args, int device) {
    KernelRecord *kernel{};
    RT_CHECK(lookupKernel(func, &kernel));
    RT_CHECK(activateDevice(device));
    LibreCUFunction function{};
    size_t count{};
    RT_CHECK(kernelFunction(kernel, device, &function, &count));
    if (count > 0 && args == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    std::vector<uint8_t> data;
    std::vector<size_t> offsets;
    for (size_t i = 0; i < count; i++) {
        size_t offset{}, size{};
        LC_CHECK(libreCuFuncGetParamInfo(&offset, &size, function, i));
        offsets.push_back(data.size());
        data.insert(data.end(), static_cast<uint8_t *>(args[i]), static_cast<uint8_t *>(args[i]) + size);
    }
    node->func = func;
    node->grid = grid;
    node->block = block;
    node->sharedMem = sharedMem;
    node->args = std::move(data);
    node->argOffsets = std::move(offsets);
    rebuildArgPointers(node);
    return cudaSuccess;
}

bool belongs(const CUgraph_st *graph, const CUgraphNode_st *node) {
    return node != nullptr && node->graph == graph;
}

void addEdge(CUgraphNode_st *from, CUgraphNode_st *to, const cudaGraphEdgeData *data = nullptr) {
    if (std::find(to->dependencies.begin(), to->dependencies.end(), from) == to->dependencies.end()) {
        to->dependencies.push_back(from);
        to->dependencyData.push_back(data != nullptr ? *data : cudaGraphEdgeData{});
        from->dependents.push_back(to);
    }
}

void removeEdge(CUgraphNode_st *from, CUgraphNode_st *to) {
    auto it = std::find(to->dependencies.begin(), to->dependencies.end(), from);
    if (it != to->dependencies.end()) {
        to->dependencyData.erase(to->dependencyData.begin() + (it - to->dependencies.begin()));
        to->dependencies.erase(it);
    }
    auto &dependents = from->dependents;
    dependents.erase(std::find(dependents.begin(), dependents.end(), to));
}

cudaGraphEdgeData edgeData(const CUgraphNode_st *from, const CUgraphNode_st *to) {
    auto it = std::find(to->dependencies.begin(), to->dependencies.end(), from);
    return it != to->dependencies.end() ? to->dependencyData[it - to->dependencies.begin()] : cudaGraphEdgeData{};
}

/**
 * Like CUDA: a programmatic edge connects kernel nodes from their programmatic or launch completion port; other edges
 * use the default ports
 */
bool validEdge(cudaGraphNodeType from, cudaGraphNodeType to, const cudaGraphEdgeData *data) {
    if (data == nullptr) {
        return true;
    }
    if (data->to_port != 0) {
        return false;
    }
    if (data->type == cudaGraphDependencyTypeProgrammatic) {
        return from == cudaGraphNodeTypeKernel && to == cudaGraphNodeTypeKernel &&
               (data->from_port == cudaGraphKernelNodePortProgrammatic ||
                data->from_port == cudaGraphKernelNodePortLaunchCompletion);
    }
    return data->type == cudaGraphDependencyTypeDefault && data->from_port == cudaGraphKernelNodePortDefault;
}

/**
 * Adds a node (taking ownership) depending on the given nodes of the graph
 */
cudaError_t addNode(CUgraph_st *graph, CUgraphNode_st *node, const cudaGraphNode_t *dependencies, size_t count,
                    cudaGraphNode_t *pNode) {
    if (graph == nullptr || (count > 0 && dependencies == nullptr)) {
        delete node;
        return recordError(cudaErrorInvalidValue);
    }
    for (size_t i = 0; i < count; i++) {
        if (!belongs(graph, dependencies[i])) {
            delete node;
            return recordError(cudaErrorInvalidValue);
        }
    }
    node->graph = graph;
    node->localId = graph->nextLocalId++;
    graph->nodes.push_back(node);
    for (size_t i = 0; i < count; i++) {
        addEdge(dependencies[i], node);
    }
    if (pNode != nullptr) {
        *pNode = node;
    }
    return cudaSuccess;
}

/**
 * Copies a graph; mapping (optional) gets each node's copy
 */
CUgraph_st *cloneGraph(const CUgraph_st &source, std::unordered_map<const CUgraphNode_st *, CUgraphNode_st *> *mapping) {
    auto *clone = new CUgraph_st{};
    std::unordered_map<const CUgraphNode_st *, CUgraphNode_st *> copies;
    for (const CUgraphNode_st *node: source.nodes) {
        auto *copy = new CUgraphNode_st(*node);
        copy->graph = clone;
        copy->toolsId = g_nextToolsId++;
        copy->dependencies.clear();
        copy->dependencyData.clear();
        copy->dependents.clear();
        copy->child = node->child != nullptr ? cloneGraph(*node->child, nullptr) : nullptr;
        for (CUgraph_st *&body: copy->bodies) {
            body = cloneGraph(*body, nullptr);
        }
        rebuildArgPointers(copy);
        clone->nodes.push_back(copy);
        copies[node] = copy;
    }
    for (const CUgraphNode_st *node: source.nodes) {
        for (size_t i = 0; i < node->dependencies.size(); i++) {
            addEdge(copies[node->dependencies[i]], copies[node], &node->dependencyData[i]);
        }
    }
    clone->nextLocalId = source.nextLocalId;
    clone->conditionalHandles = source.conditionalHandles;
    // the copy holds its own references on the user objects
    clone->userObjects = source.userObjects;
    for (auto &[object, count]: clone->userObjects) {
        object->references += count;
    }
    if (mapping != nullptr) {
        *mapping = std::move(copies);
    }
    return clone;
}

/**
 * The nodes in an order that respects the dependencies; false if they form a cycle
 */
bool topologicalOrder(const CUgraph_st &graph, std::vector<CUgraphNode_st *> *pOrder) {
    std::unordered_map<const CUgraphNode_st *, size_t> pending;
    std::vector<CUgraphNode_st *> ready, order;
    for (CUgraphNode_st *node: graph.nodes) {
        pending[node] = node->dependencies.size();
        if (node->dependencies.empty()) {
            ready.push_back(node);
        }
    }
    // in creation order where possible (captured work replays in the order it was submitted)
    std::reverse(ready.begin(), ready.end());
    while (!ready.empty()) {
        CUgraphNode_st *node = ready.back();
        ready.pop_back();
        order.push_back(node);
        std::vector<CUgraphNode_st *> next;
        for (CUgraphNode_st *dependent: node->dependents) {
            if (--pending[dependent] == 0) {
                next.push_back(dependent);
            }
        }
        ready.insert(ready.end(), next.rbegin(), next.rend());
    }
    *pOrder = std::move(order);
    return pOrder->size() == graph.nodes.size();
}

cudaError_t runMemset(const cudaMemsetParams &p, cudaStream_t handle) {
    if (p.elementSize != 1 && p.elementSize != 2 && p.elementSize != 4) {
        return recordError(cudaErrorInvalidValue);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    RT_CHECK(beginOperation(stream));
    for (size_t row = 0; row < std::max<size_t>(1, p.height); row++) {
        LC_CHECK(libreCuMemsetAsync(static_cast<uint8_t *>(p.dst) + row * p.pitch, p.value, p.elementSize, p.width,
                                    stream->stream));
    }
    return endOperation(stream);
}

cudaError_t runGraph(const CUgraph_st &graph, const std::vector<CUgraphNode_st *> &order, cudaStream_t stream);

bool hasMemoryNodes(const CUgraph_st &graph) {
    for (const CUgraphNode_st *node: graph.nodes) {
        if (node->type == cudaGraphNodeTypeMemAlloc || node->type == cudaGraphNodeTypeMemFree ||
            (node->child != nullptr && hasMemoryNodes(*node->child))) {
            return true;
        }
        for (const CUgraph_st *body: node->bodies) {
            if (hasMemoryNodes(*body)) {
                return true;
            }
        }
    }
    return false;
}

cudaError_t runBody(const CUgraph_st &graph, cudaStream_t handle) {
    std::vector<CUgraphNode_st *> order;
    if (!topologicalOrder(graph, &order)) {
        return recordError(cudaErrorInvalidValue);
    }
    return runGraph(graph, order, handle);
}

/**
 * A conditional node: waits for the stream's preceding work (which may set the condition), reads the condition and
 * runs the selected body graph(s) on the stream
 */
cudaError_t runConditional(CUgraphNode_st *node, cudaStream_t handle) {
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    unsigned int value{};
    auto read = [&] { return memcpyOnStream(&value, node->conditional->slot, sizeof(value), stream, true); };
    RT_CHECK(read());
    switch (node->conditionalType) {
        case cudaGraphCondTypeIf: {
            const CUgraph_st *body = value != 0 ? node->bodies[0] : node->bodies.size() > 1 ? node->bodies[1] : nullptr;
            return body != nullptr ? runBody(*body, handle) : cudaSuccess;
        }
        case cudaGraphCondTypeWhile:
            while (value != 0) {
                RT_CHECK(runBody(*node->bodies[0], handle));
                RT_CHECK(read());
            }
            return cudaSuccess;
        case cudaGraphCondTypeSwitch:
            return value < node->bodies.size() ? runBody(*node->bodies[value], handle) : cudaSuccess;
        default:
            return recordError(cudaErrorNotSupported);
    }
}

// the conditional handles of a graph and its child and body graphs
void conditionalHandles(const CUgraph_st &graph, std::vector<ConditionalHandle *> *pOut) {
    for (const auto &handle: graph.conditionalHandles) {
        if (std::find(pOut->begin(), pOut->end(), handle.get()) == pOut->end()) {
            pOut->push_back(handle.get());
        }
    }
    for (const CUgraphNode_st *node: graph.nodes) {
        if (node->child != nullptr) {
            conditionalHandles(*node->child, pOut);
        }
        for (const CUgraph_st *body: node->bodies) {
            conditionalHandles(*body, pOut);
        }
    }
}

cudaError_t runNode(CUgraphNode_st *node, cudaStream_t handle) {
    if (!node->enabled) {
        return cudaSuccess;
    }
    switch (node->type) {
        case cudaGraphNodeTypeKernel:
            return launch(node->func, node->grid, node->block, node->argPtrs.data(), node->sharedMem, handle,
                          node->cooperative, node->hasCluster ? &node->cluster : nullptr);
        case cudaGraphNodeTypeMemcpy:
            return memcpy3D(&node->copy, handle, false);
        case cudaGraphNodeTypeMemset:
            return runMemset(node->memset, handle);
        case cudaGraphNodeTypeHost:
            return cudaLaunchHostFunc(handle, node->host.fn, node->host.userData);
        case cudaGraphNodeTypeGraph: {
            std::vector<CUgraphNode_st *> order;
            if (!topologicalOrder(*node->child, &order)) {
                return recordError(cudaErrorInvalidValue);
            }
            return runGraph(*node->child, order, handle);
        }
        case cudaGraphNodeTypeEventRecord:
            return cudaEventRecord(node->event, handle);
        case cudaGraphNodeTypeWaitEvent:
            return cudaStreamWaitEvent(handle, node->event, 0);
        case cudaGraphNodeTypeEmpty:
        case cudaGraphNodeTypeMemAlloc:
        case cudaGraphNodeTypeMemFree:
            // graph memory exists while the graph does (see above)
            return cudaSuccess;
        case cudaGraphNodeTypeConditional:
            return runConditional(node, handle);
        default:
            return recordError(cudaErrorNotSupported);
    }
}

cudaError_t runGraph(const CUgraph_st &, const std::vector<CUgraphNode_st *> &order, cudaStream_t stream) {
    for (CUgraphNode_st *node: order) {
        RT_CHECK(runNode(node, stream));
    }
    return cudaSuccess;
}

/**
 * At most this many lanes (internal streams + the launch stream); LIBRECUDA_GRAPH_LANES overrides it (1: replay
 * serially on the launch stream)
 */
unsigned int maxGraphLanes() {
    static const unsigned int lanes = [] {
        const char *env = getenv("LIBRECUDA_GRAPH_LANES");
        const long n = env != nullptr ? strtol(env, nullptr, 10) : 8;
        return static_cast<unsigned int>(std::clamp(n, 1L, 64L));
    }();
    return lanes;
}

/**
 * Splits the executable graph's nodes into lanes: a node continues the lane of a dependency that is the last node of
 * its lane so far, other nodes start a new lane. Lanes beyond the maximum share streams (round robin): nodes on one
 * stream run in topological order, which respects their dependencies.
 */
void assignLanes(CUgraphExec_st *exec) {
    const std::vector<CUgraphNode_st *> &order = exec->order;
    std::unordered_map<const CUgraphNode_st *, size_t> position;
    for (size_t i = 0; i < order.size(); i++) {
        position[order[i]] = i;
    }
    std::vector<size_t> lane_tails;
    std::vector<unsigned int> logical(order.size());
    for (size_t i = 0; i < order.size(); i++) {
        unsigned int lane = UINT_MAX;
        for (const CUgraphNode_st *dependency: order[i]->dependencies) {
            const size_t p = position[dependency];
            if (lane_tails[logical[p]] == p) {
                lane = logical[p];
                break;
            }
        }
        if (lane == UINT_MAX) {
            lane = static_cast<unsigned int>(lane_tails.size());
            lane_tails.push_back(i);
        }
        logical[i] = lane;
        lane_tails[lane] = i;
    }
    const unsigned int max_lanes = maxGraphLanes();
    exec->laneCount = std::max<unsigned int>(1, std::min<unsigned int>(lane_tails.size(), max_lanes));
    exec->lanes.assign(order.size(), 0);
    exec->crossDependencies.assign(order.size(), {});
    exec->signals.assign(order.size(), false);
    for (size_t i = 0; i < order.size(); i++) {
        exec->lanes[i] = logical[i] % max_lanes;
    }
    for (size_t i = 0; i < order.size(); i++) {
        for (const CUgraphNode_st *dependency: order[i]->dependencies) {
            const size_t p = position[dependency];
            if (exec->lanes[p] != exec->lanes[i]) {
                exec->crossDependencies[i].push_back(p);
                exec->signals[p] = true;
            }
        }
    }
}

/**
 * The executable graph's internal streams and events on the device, created on its first launch there (again after a
 * reset of the device, which destroyed the streams)
 */
cudaError_t laneResources(CUgraphExec_st *exec, int device, CUgraphExec_st::Resources **pOut) {
    CUgraphExec_st::Resources &r = exec->resources[device];
    if (r.start != nullptr && r.generation == g_devices[device].generation) {
        *pOut = &r;
        return cudaSuccess;
    }
    // events survive a reset as handles; the streams are gone
    for (cudaEvent_t event: r.nodeEvents) {
        if (event != nullptr) {
            cudaEventDestroy(event);
        }
    }
    for (cudaEvent_t event: r.laneEnds) {
        cudaEventDestroy(event);
    }
    if (r.start != nullptr) {
        cudaEventDestroy(r.start);
    }
    r = CUgraphExec_st::Resources{.generation = g_devices[device].generation};
    for (unsigned int lane = 1; lane < exec->laneCount; lane++) {
        cudaStream_t stream{};
        RT_CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
        r.streams.push_back(stream);
        cudaEvent_t end{};
        RT_CHECK(cudaEventCreateWithFlags(&end, cudaEventDisableTiming));
        r.laneEnds.push_back(end);
    }
    r.nodeEvents.assign(exec->order.size(), nullptr);
    for (size_t i = 0; i < exec->order.size(); i++) {
        if (exec->signals[i]) {
            RT_CHECK(cudaEventCreateWithFlags(&r.nodeEvents[i], cudaEventDisableTiming));
        }
    }
    RT_CHECK(cudaEventCreateWithFlags(&r.start, cudaEventDisableTiming));
    *pOut = &r;
    return cudaSuccess;
}

/**
 * Groups the kernel nodes of each lane into segments (see CUgraphExec_st::segments)
 */
void computeSegments(CUgraphExec_st *exec) {
    const size_t n = exec->order.size();
    exec->segments.clear();
    exec->segmentOf.assign(n, -1);
    // per lane: the open segment and the lane's last node so far
    std::unordered_map<unsigned int, int> open;
    for (size_t i = 0; i < n; i++) {
        const CUgraphNode_st *node = exec->order[i];
        const unsigned int lane = exec->lanes[i];
        const bool eligible = node->type == cudaGraphNodeTypeKernel && !node->cooperative;
        auto it = open.find(lane);
        const bool extend = eligible && it != open.end() && it->second >= 0 && exec->crossDependencies[i].empty() &&
                            !exec->signals[exec->segments[it->second].back()];
        if (extend) {
            exec->segments[it->second].push_back(i);
            exec->segmentOf[i] = it->second;
        } else if (eligible) {
            exec->segments.push_back({i});
            exec->segmentOf[i] = static_cast<int>(exec->segments.size()) - 1;
            open[lane] = exec->segmentOf[i];
        } else {
            open[lane] = -1;
        }
    }
}

void destroySegmentLists(CUgraphExec_st *exec) {
    std::vector<std::pair<int, LibreCUcommandList>> lists = std::move(exec->retiredLists);
    for (auto &[device, segment_lists]: exec->segmentLists) {
        if (segment_lists.generation != g_devices[device].generation) {
            continue; // freed with the context
        }
        for (LibreCUcommandList list: segment_lists.lists) {
            if (list != nullptr) {
                lists.emplace_back(device, list);
            }
        }
    }
    exec->segmentLists.clear();
    std::unordered_set<int> devices;
    for (auto &[device, list]: lists) {
        devices.insert(device);
    }
    // the GPU may still read the lists of earlier launches
    for (int device: devices) {
        if (g_devices[device].ctx != nullptr && activateDevice(device) == cudaSuccess) {
            synchronizeDevice(device);
        }
    }
    for (auto &[device, list]: lists) {
        libreCuCommandListDestroy(list);
    }
    activateCurrentDevice();
}

/**
 * Runs a segment of kernel nodes: as its command list, built on first use, or node by node if the driver can't
 * record one of its kernels
 */
cudaError_t runSegment(CUgraphExec_st *exec, int segment, cudaStream_t handle) {
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    CUgraphExec_st::SegmentLists &lists = exec->segmentLists[stream->device];
    if (lists.generation != g_devices[stream->device].generation || lists.lists.size() != exec->segments.size()) {
        // first use on the device (or after a reset, which freed the lists with the context)
        lists = CUgraphExec_st::SegmentLists{.generation = g_devices[stream->device].generation};
        lists.lists.assign(exec->segments.size(), nullptr);
        lists.nodeByNode.assign(exec->segments.size(), false);
    }
    const std::vector<size_t> &positions = exec->segments[segment];
    if (lists.lists[segment] == nullptr && !lists.nodeByNode[segment]) {
        LibreCUcommandList list{};
        LC_CHECK(libreCuCommandListCreate(&list));
        size_t kernels = 0;
        bool recorded = true;
        for (size_t position: positions) {
            const CUgraphNode_st *node = exec->order[position];
            if (!node->enabled) {
                continue;
            }
            KernelRecord *kernel{};
            LibreCUFunction function{};
            size_t count{};
            if (lookupKernel(node->func, &kernel) != cudaSuccess ||
                kernelFunction(kernel, stream->device, &function, &count) != cudaSuccess) {
                recorded = false;
                break;
            }
            const uint32_t cluster[3] = {node->cluster.x, node->cluster.y, node->cluster.z};
            if (libreCuCommandListAddKernel(list, function, node->grid.x, node->grid.y, node->grid.z, node->block.x,
                                            node->block.y, node->block.z, node->sharedMem,
                                            const_cast<void **>(node->argPtrs.data()), count,
                                            node->hasCluster ? cluster : nullptr) != 0) {
                recorded = false;
                break;
            }
            kernels++;
        }
        if (!recorded || kernels == 0) {
            libreCuCommandListDestroy(list);
            lists.nodeByNode[segment] = true;
        } else {
            lists.lists[segment] = list;
        }
    }
    if (lists.nodeByNode[segment]) {
        for (size_t position: positions) {
            RT_CHECK(runNode(exec->order[position], handle));
        }
        return cudaSuccess;
    }
    RT_CHECK(beginOperation(stream));
    LC_CHECK(libreCuCommandListLaunch(lists.lists[segment], stream->stream));
    return endOperation(stream);
}

void destroyLaneResources(CUgraphExec_st *exec) {
    for (auto &[device, r]: exec->resources) {
        const bool streams_alive = r.generation == g_devices[device].generation;
        for (cudaStream_t stream: r.streams) {
            if (streams_alive) {
                cudaStreamDestroy(stream);
            }
        }
        for (cudaEvent_t event: r.nodeEvents) {
            if (event != nullptr) {
                cudaEventDestroy(event);
            }
        }
        for (cudaEvent_t event: r.laneEnds) {
            cudaEventDestroy(event);
        }
        if (r.start != nullptr) {
            cudaEventDestroy(r.start);
        }
    }
    exec->resources.clear();
}

// live executable graphs (device code may pass any value to cudaGraphLaunch)
std::unordered_set<CUgraphExec_st *> g_liveExecs{};
// tail launches requested by device code during the outermost graph launch of this thread (run after it)
thread_local std::vector<CUgraphExec_st *> *t_tailLaunches = nullptr;

// sets the executable graph kernels on the stream see as %current_graph_exec
void setStreamGraphExec(CUstream_st *stream, CUgraphExec_st *exec) {
    stream->graphExec = exec;
    libreCuStreamSetGraphExec(stream->stream, reinterpret_cast<uint64_t>(exec));
}

cudaError_t launchExec(CUgraphExec_st *exec, cudaStream_t handle, CUstream_st *stream);
cudaError_t replayExec(CUgraphExec_st *exec, cudaStream_t handle, CUstream_st *stream);

cudaError_t runDeviceGraphLaunches(cudaStream_t handle) {
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    while (true) {
        uint64_t execs[16], streams[16];
        size_t count{};
        LC_CHECK(libreCuCtxTakeDeviceGraphLaunches(execs, streams, 16, &count));
        if (count == 0) {
            return cudaSuccess;
        }
        for (size_t i = 0; i < count; i++) {
            auto *exec = reinterpret_cast<CUgraphExec_st *>(execs[i]);
            if (g_liveExecs.count(exec) == 0 || !(exec->flags & cudaGraphInstantiateFlagDeviceLaunch)) {
                return recordError(cudaErrorInvalidValue);
            }
            // cudaStreamGraphTailLaunch (cuda_device_runtime_api.h)
            constexpr uint64_t STREAM_GRAPH_TAIL_LAUNCH = 0x0100000000000000ull;
            if (streams[i] == STREAM_GRAPH_TAIL_LAUNCH && t_tailLaunches != nullptr) {
                // after the launching graph
                t_tailLaunches->push_back(exec);
            } else {
                // fire and forget: right after the launching kernel
                RT_CHECK(launchExec(exec, handle, stream));
            }
        }
    }
}

/**
 * Replays an executable graph, its lanes on the launch stream and the internal streams
 */
cudaError_t launchExec(CUgraphExec_st *exec, cudaStream_t handle, CUstream_st *stream) {
    // the outermost launch runs the tail launches its graphs request once they are done
    std::vector<CUgraphExec_st *> tails;
    const bool owns_tails = t_tailLaunches == nullptr;
    if (owns_tails) {
        t_tailLaunches = &tails;
    }
    struct TailScope {
        bool owns;
        ~TailScope() {
            if (owns) {
                t_tailLaunches = nullptr;
            }
        }
    } tail_scope{owns_tails};
    RT_CHECK(replayExec(exec, handle, stream));
    if (owns_tails) {
        for (size_t i = 0; i < tails.size(); i++) {
            CUgraphExec_st *tail = tails[i];
            RT_CHECK(replayExec(tail, handle, stream));
        }
    }
    return cudaSuccess;
}

/**
 * Replays an executable graph, its lanes on the launch stream and the internal streams
 */
cudaError_t replayExec(CUgraphExec_st *exec, cudaStream_t handle, CUstream_st *stream) {
    // conditions with cudaGraphCondAssignDefault start each launch with their default value
    std::vector<ConditionalHandle *> handles;
    conditionalHandles(exec->graph, &handles);
    for (const ConditionalHandle *conditional: handles) {
        if (conditional->assignDefault) {
            RT_CHECK(runMemset(cudaMemsetParams{conditional->slot, 0, conditional->defaultValue, 4, 1, 1}, handle));
        }
    }
    if (exec->segmentsStale) {
        // parameters changed: the lists are rebuilt; the old ones may still be in use
        for (auto &[device, lists]: exec->segmentLists) {
            for (LibreCUcommandList list: lists.lists) {
                if (list != nullptr && lists.generation == g_devices[device].generation) {
                    exec->retiredLists.emplace_back(device, list);
                }
            }
        }
        exec->segmentLists.clear();
        computeSegments(exec);
        exec->segmentsStale = false;
    }
    CUgraphExec_st::Resources *r{};
    if (exec->laneCount > 1) {
        RT_CHECK(laneResources(exec, stream->device, &r));
        RT_CHECK(cudaEventRecord(r->start, handle));
        for (cudaStream_t lane: r->streams) {
            RT_CHECK(cudaStreamWaitEvent(lane, r->start, 0));
        }
    }
    auto lane_stream = [&](unsigned int lane) { return lane == 0 ? handle : r->streams[lane - 1]; };
    // kernels of the graph see it as %current_graph_exec (restored for an enclosing graph afterwards)
    std::vector<std::pair<CUstream_st *, CUgraphExec_st *>> previous;
    previous.emplace_back(stream, stream->graphExec);
    if (r != nullptr) {
        for (cudaStream_t lane: r->streams) {
            previous.emplace_back(lane, lane->graphExec);
        }
    }
    for (auto &[s, old]: previous) {
        setStreamGraphExec(s, exec);
    }
    struct GraphExecScope {
        std::vector<std::pair<CUstream_st *, CUgraphExec_st *>> &previous;
        ~GraphExecScope() {
            for (auto &[s, old]: previous) {
                setStreamGraphExec(s, old);
            }
        }
    } graph_exec_scope{previous};
    // nodes already run as part of a segment
    std::vector<bool> done(exec->order.size(), false);
    for (size_t i = 0; i < exec->order.size(); i++) {
        if (done[i]) {
            continue;
        }
        const cudaStream_t s = lane_stream(exec->lanes[i]);
        for (size_t dependency: exec->crossDependencies[i]) {
            RT_CHECK(cudaStreamWaitEvent(s, r->nodeEvents[dependency], 0));
        }
        size_t last = i;
        if (exec->segmentOf[i] >= 0) {
            const int segment = exec->segmentOf[i];
            RT_CHECK(runSegment(exec, segment, s));
            for (size_t position: exec->segments[segment]) {
                done[position] = true;
            }
            last = exec->segments[segment].back();
        } else {
            RT_CHECK(runNode(exec->order[i], s));
        }
        if (exec->signals[last]) {
            RT_CHECK(cudaEventRecord(r->nodeEvents[last], s));
        }
    }
    if (r == nullptr) {
        return cudaSuccess;
    }
    for (size_t lane = 0; lane < r->streams.size(); lane++) {
        RT_CHECK(cudaEventRecord(r->laneEnds[lane], r->streams[lane]));
        RT_CHECK(cudaStreamWaitEvent(handle, r->laneEnds[lane], 0));
    }
    return cudaSuccess;
}

// graph memory by address (cudaFree of it keeps it)
std::unordered_map<void *, GraphAllocation *> g_graphAllocations{};

cudaError_t newGraphAllocation(int device, size_t size, std::shared_ptr<GraphAllocation> *pOut) {
    if (size == 0 || device < 0 || device >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateDevice(device));
    void *ptr{};
    const libreCudaStatus_t status = libreCuMemAlloc(&ptr, size, false);
    activateCurrentDevice();
    LC_CHECK(status);
    auto allocation = std::make_shared<GraphAllocation>();
    allocation->ptr = ptr;
    allocation->size = size;
    allocation->device = device;
    allocation->generation = g_devices[device].generation;
    g_graphAllocations[ptr] = allocation.get();
    DeviceState &state = g_devices[device];
    state.graphMemUsed += size;
    state.graphMemHigh = std::max(state.graphMemHigh, state.graphMemUsed);
    *pOut = std::move(allocation);
    return cudaSuccess;
}

void invalidate(CaptureState *capture) {
    capture->invalidated = true;
}

bool isGraphAllocation(const void *ptr) {
    return g_graphAllocations.count(const_cast<void *>(ptr)) != 0;
}
} // namespace

// conditional handles by value (the device address of the condition)
static std::unordered_map<unsigned long long, std::weak_ptr<ConditionalHandle>> g_conditionalHandles{};

ConditionalHandle::~ConditionalHandle() {
    g_conditionalHandles.erase(reinterpret_cast<unsigned long long>(slot));
    const DeviceState &state = g_devices[device];
    if (state.ctx != nullptr && generation == state.generation) {
        if (activateDevice(device) == cudaSuccess) {
            synchronizeDevice(device);
            libreCuMemFree(slot);
        }
        activateCurrentDevice();
    }
}

GraphAllocation::~GraphAllocation() {
    g_graphAllocations.erase(ptr);
    DeviceState &state = g_devices[device];
    state.graphMemUsed -= std::min(state.graphMemUsed, size);
    // freed with the context by a reset of the device
    if (state.ctx != nullptr && generation == state.generation) {
        // work of the graph may still use it
        if (activateDevice(device) == cudaSuccess) {
            synchronizeDevice(device);
            libreCuMemFree(ptr);
        }
        activateCurrentDevice();
    }
}

// capture hooks (declared at the top)
namespace {
bool capturing(const CUstream_st *stream) {
    return stream != nullptr && stream->capture != nullptr;
}

/**
 * Adds a node to the capture the stream takes part in, after the stream's tail
 */
cudaError_t captureNode(CUstream_st *stream, CUgraphNode_st *node) {
    CaptureState *capture = stream->capture;
    if (capture->invalidated) {
        delete node;
        return recordError(cudaErrorStreamCaptureInvalidated);
    }
    std::vector<CUgraphNode_st *> &tail = capture->tails[stream];
    RT_CHECK(addNode(capture->graph, node, tail.data(), tail.size(), nullptr));
    tail.assign(1, node);
    return cudaSuccess;
}

cudaError_t captureKernel(CUstream_st *stream, const void *func, dim3 grid, dim3 block, void **args, size_t sharedMem,
                          bool cooperative, const dim3 *cluster) {
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeKernel;
    node->cooperative = cooperative;
    if (cluster != nullptr) {
        node->hasCluster = true;
        node->cluster = *cluster;
    }
    const cudaError_t error = setKernel(node, func, grid, block, static_cast<unsigned int>(sharedMem), args,
                                        stream->device);
    if (error != cudaSuccess) {
        delete node;
        invalidate(stream->capture);
        return error;
    }
    RT_CHECK(captureNode(stream, node));
    if (t_programmaticLaunch) {
        // programmatic dependent launch: programmatic edges from the preceding kernels
        for (size_t i = 0; i < node->dependencies.size(); i++) {
            if (node->dependencies[i]->type == cudaGraphNodeTypeKernel) {
                node->dependencyData[i].from_port = cudaGraphKernelNodePortProgrammatic;
                node->dependencyData[i].type = cudaGraphDependencyTypeProgrammatic;
            }
        }
    }
    return cudaSuccess;
}

cudaError_t captureCopy(CUstream_st *stream, const cudaMemcpy3DParms &params) {
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemcpy;
    node->copy = params;
    return captureNode(stream, node);
}

cudaError_t captureMemset(CUstream_st *stream, const cudaMemsetParams &params) {
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemset;
    node->memset = params;
    return captureNode(stream, node);
}

cudaError_t captureUnsupported(CUstream_st *stream) {
    invalidate(stream->capture);
    return recordError(cudaErrorStreamCaptureUnsupported);
}

cudaError_t captureMallocAsync(CUstream_st *stream, void **devPtr, size_t size) {
    if (devPtr == nullptr || size == 0) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemAlloc;
    const cudaError_t error = newGraphAllocation(stream->device, size, &node->allocation);
    if (error != cudaSuccess) {
        delete node;
        invalidate(stream->capture);
        return error;
    }
    node->allocParams.poolProps.allocType = cudaMemAllocationTypePinned;
    node->allocParams.poolProps.location = {cudaMemLocationTypeDevice, stream->device};
    node->allocParams.bytesize = size;
    node->allocParams.dptr = node->allocation->ptr;
    *devPtr = node->allocation->ptr;
    return captureNode(stream, node);
}

cudaError_t captureFreeAsync(CUstream_st *stream, void *devPtr) {
    // only graph memory (like CUDA)
    if (!isGraphAllocation(devPtr)) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemFree;
    node->freePtr = devPtr;
    return captureNode(stream, node);
}

cudaError_t prohibitedDuringCapture() {
    if (t_captureMode == cudaStreamCaptureModeRelaxed) {
        return cudaSuccess;
    }
    for (CaptureState *capture: g_captures) {
        if (capture->mode == cudaStreamCaptureModeGlobal ||
            (capture->mode == cudaStreamCaptureModeThreadLocal && capture->thread == std::this_thread::get_id())) {
            invalidate(capture);
            return recordError(cudaErrorStreamCaptureUnsupported);
        }
    }
    return cudaSuccess;
}

cudaError_t checkImplicitCapture(int device) {
    // the legacy default stream synchronizes with blocking streams: not allowed while one of them is capturing
    cudaError_t error = cudaSuccess;
    for (CUstream_st *stream: g_devices[device].streams) {
        if (stream->blocking && capturing(stream)) {
            invalidate(stream->capture);
            error = cudaErrorStreamCaptureImplicit;
        }
    }
    return error == cudaSuccess ? cudaSuccess : recordError(error);
}

/**
 * A stream that is destroyed leaves its capture, which can't be completed anymore (its graph is discarded if it was
 * the origin stream)
 */
void leaveCapture(CUstream_st *stream) {
    CaptureState *capture = stream->capture;
    if (capture == nullptr) {
        return;
    }
    invalidate(capture);
    if (capture->origin == stream) {
        endCapture(capture);
        if (capture->ownsGraph) {
            delete capture->graph;
        }
        delete capture;
    } else {
        capture->tails.erase(stream);
        stream->capture = nullptr;
    }
}

/**
 * Ends a capture: the streams and events taking part leave it
 */
void endCapture(CaptureState *capture) {
    for (auto &[stream, tail]: capture->tails) {
        stream->capture = nullptr;
    }
    for (CUevent_st *event: capture->events) {
        event->capture = nullptr;
        event->capturedNodes.clear();
    }
    g_captures.erase(capture);
}
} // namespace

// ---- stream capture API

static cudaError_t beginCapture(cudaStream_t handle, CUgraph_st *graph, bool ownsGraph,
                                const cudaGraphNode_t *dependencies, size_t count, cudaStreamCaptureMode mode) {
    // the legacy default stream can't be captured
    if (isDefaultStreamHandle(handle)) {
        return recordError(cudaErrorStreamCaptureUnsupported);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (stream->capture != nullptr) {
        return recordError(cudaErrorIllegalState);
    }
    for (size_t i = 0; i < count; i++) {
        if (!belongs(graph, dependencies[i])) {
            return recordError(cudaErrorInvalidValue);
        }
    }
    auto *capture = new CaptureState{.graph = graph, .ownsGraph = ownsGraph, .mode = mode,
                                     .thread = std::this_thread::get_id(), .id = g_nextCaptureId++,
                                     .origin = stream};
    capture->tails[stream].assign(dependencies, dependencies + count);
    stream->capture = capture;
    g_captures.insert(capture);
    return cudaSuccess;
}

cudaError_t cudaStreamBeginCapture(cudaStream_t stream, enum cudaStreamCaptureMode mode) {
    API_LOCK();
    auto *graph = new CUgraph_st{};
    const cudaError_t error = beginCapture(stream, graph, true, nullptr, 0, mode);
    if (error != cudaSuccess) {
        delete graph;
    }
    return error;
}

cudaError_t cudaStreamBeginCaptureToGraph(cudaStream_t stream, cudaGraph_t graph, const cudaGraphNode_t *dependencies,
                                          const cudaGraphEdgeData *, size_t numDependencies,
                                          enum cudaStreamCaptureMode mode) {
    API_LOCK();
    if (graph == nullptr || (numDependencies > 0 && dependencies == nullptr)) {
        return recordError(cudaErrorInvalidValue);
    }
    return beginCapture(stream, graph, false, dependencies, numDependencies, mode);
}

cudaError_t cudaStreamEndCapture(cudaStream_t handle, cudaGraph_t *pGraph) {
    API_LOCK();
    if (pGraph == nullptr || isDefaultStreamHandle(handle)) {
        return recordError(cudaErrorInvalidValue);
    }
    CUstream_st *stream = handle;
    CaptureState *capture = stream->capture;
    if (capture == nullptr) {
        return recordError(cudaErrorIllegalState);
    }
    if (capture->origin != stream) {
        invalidate(capture);
        return recordError(cudaErrorStreamCaptureUnmatched);
    }
    // every stream that joined must have been joined back into the origin stream
    std::unordered_set<const CUgraphNode_st *> joined;
    std::vector<const CUgraphNode_st *> pending(capture->tails[stream].begin(), capture->tails[stream].end());
    while (!pending.empty()) {
        const CUgraphNode_st *node = pending.back();
        pending.pop_back();
        if (joined.insert(node).second) {
            pending.insert(pending.end(), node->dependencies.begin(), node->dependencies.end());
        }
    }
    cudaError_t error = cudaSuccess;
    for (auto &[other, tail]: capture->tails) {
        for (const CUgraphNode_st *node: tail) {
            if (other != stream && joined.count(node) == 0) {
                error = cudaErrorStreamCaptureUnjoined;
            }
        }
    }
    if (error == cudaSuccess && capture->invalidated) {
        error = cudaErrorStreamCaptureInvalidated;
    }
    endCapture(capture);
    if (error != cudaSuccess) {
        if (capture->ownsGraph) {
            delete capture->graph;
        }
        delete capture;
        *pGraph = nullptr;
        return recordError(error);
    }
    *pGraph = capture->graph;
    delete capture;
    return cudaSuccess;
}

cudaError_t cudaStreamIsCapturing(cudaStream_t handle, enum cudaStreamCaptureStatus *pCaptureStatus) {
    API_LOCK();
    if (pCaptureStatus == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    if (isDefaultStreamHandle(handle)) {
        *pCaptureStatus = cudaStreamCaptureStatusNone;
        return cudaSuccess;
    }
    const CaptureState *capture = handle->capture;
    *pCaptureStatus = capture == nullptr ? cudaStreamCaptureStatusNone
                      : capture->invalidated ? cudaStreamCaptureStatusInvalidated : cudaStreamCaptureStatusActive;
    return cudaSuccess;
}

cudaError_t cudaStreamGetCaptureInfo(cudaStream_t handle, enum cudaStreamCaptureStatus *captureStatus_out,
                                     unsigned long long *id_out, cudaGraph_t *graph_out,
                                     const cudaGraphNode_t **dependencies_out, const cudaGraphEdgeData **edgeData_out,
                                     size_t *numDependencies_out) {
    API_LOCK();
    if (captureStatus_out == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    CaptureState *capture = isDefaultStreamHandle(handle) ? nullptr : handle->capture;
    if (capture == nullptr) {
        *captureStatus_out = cudaStreamCaptureStatusNone;
        return cudaSuccess;
    }
    *captureStatus_out = capture->invalidated ? cudaStreamCaptureStatusInvalidated : cudaStreamCaptureStatusActive;
    const std::vector<CUgraphNode_st *> &tail = capture->tails[handle];
    if (id_out != nullptr) {
        *id_out = capture->id;
    }
    if (graph_out != nullptr) {
        *graph_out = capture->graph;
    }
    if (dependencies_out != nullptr) {
        *dependencies_out = tail.empty() ? nullptr : tail.data();
    }
    if (edgeData_out != nullptr) {
        capture->edgeData.assign(tail.size(), cudaGraphEdgeData{});
        *edgeData_out = tail.empty() ? nullptr : capture->edgeData.data();
    }
    if (numDependencies_out != nullptr) {
        *numDependencies_out = tail.size();
    }
    return cudaSuccess;
}

cudaError_t cudaStreamUpdateCaptureDependencies(cudaStream_t handle, cudaGraphNode_t *dependencies,
                                                const cudaGraphEdgeData *, size_t numDependencies,
                                                unsigned int flags) {
    API_LOCK();
    if (isDefaultStreamHandle(handle) || handle->capture == nullptr) {
        return recordError(cudaErrorIllegalState);
    }
    CaptureState *capture = handle->capture;
    for (size_t i = 0; i < numDependencies; i++) {
        if (!belongs(capture->graph, dependencies[i])) {
            return recordError(cudaErrorInvalidValue);
        }
    }
    std::vector<CUgraphNode_st *> &tail = capture->tails[handle];
    if (flags == cudaStreamSetCaptureDependencies) {
        tail.clear();
    }
    for (size_t i = 0; i < numDependencies; i++) {
        if (std::find(tail.begin(), tail.end(), dependencies[i]) == tail.end()) {
            tail.push_back(dependencies[i]);
        }
    }
    return cudaSuccess;
}

cudaError_t cudaThreadExchangeStreamCaptureMode(enum cudaStreamCaptureMode *mode) {
    if (mode == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    std::swap(*mode, t_captureMode);
    return cudaSuccess;
}

// ---- graphs

cudaError_t cudaGraphCreate(cudaGraph_t *pGraph, unsigned int) {
    API_LOCK();
    if (pGraph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *pGraph = new CUgraph_st{};
    return cudaSuccess;
}

cudaError_t cudaGraphDestroy(cudaGraph_t graph) {
    API_LOCK();
    if (graph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    delete graph;
    return cudaSuccess;
}

cudaError_t cudaGraphClone(cudaGraph_t *pGraphClone, cudaGraph_t originalGraph) {
    API_LOCK();
    if (pGraphClone == nullptr || originalGraph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    if (hasMemoryNodes(*originalGraph)) {
        return recordError(cudaErrorNotSupported);
    }
    std::unordered_map<const CUgraphNode_st *, CUgraphNode_st *> mapping;
    *pGraphClone = cloneGraph(*originalGraph, &mapping);
    (*pGraphClone)->cloneOf = std::move(mapping);
    return cudaSuccess;
}

cudaError_t cudaGraphAddKernelNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                                   size_t numDependencies, const struct cudaKernelNodeParams *pNodeParams) {
    API_LOCK();
    if (pGraphNode == nullptr || pNodeParams == nullptr || pNodeParams->extra != nullptr) {
        return recordError(pNodeParams != nullptr && pNodeParams->extra != nullptr ? cudaErrorNotSupported
                                                                                   : cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeKernel;
    const cudaError_t error = setKernel(node, pNodeParams->func, pNodeParams->gridDim, pNodeParams->blockDim,
                                        pNodeParams->sharedMemBytes, pNodeParams->kernelParams, t_device);
    if (error != cudaSuccess) {
        delete node;
        return error;
    }
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphAddMemcpyNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                                   size_t numDependencies, const struct cudaMemcpy3DParms *pCopyParams) {
    API_LOCK();
    if (pGraphNode == nullptr || pCopyParams == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemcpy;
    node->copy = *pCopyParams;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

static cudaMemcpy3DParms linearCopy(void *dst, const void *src, size_t count) {
    cudaMemcpy3DParms p{};
    p.dstPtr.ptr = dst;
    p.dstPtr.pitch = p.dstPtr.xsize = count;
    p.dstPtr.ysize = 1;
    p.srcPtr.ptr = const_cast<void *>(src);
    p.srcPtr.pitch = p.srcPtr.xsize = count;
    p.srcPtr.ysize = 1;
    p.extent.width = count;
    p.extent.height = p.extent.depth = 1;
    p.kind = cudaMemcpyDefault;
    return p;
}

cudaError_t cudaGraphAddMemcpyNode1D(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                     const cudaGraphNode_t *pDependencies, size_t numDependencies, void *dst,
                                     const void *src, size_t count, enum cudaMemcpyKind) {
    const cudaMemcpy3DParms p = linearCopy(dst, src, count);
    return cudaGraphAddMemcpyNode(pGraphNode, graph, pDependencies, numDependencies, &p);
}

cudaError_t cudaGraphAddMemsetNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                                   size_t numDependencies, const struct cudaMemsetParams *pMemsetParams) {
    API_LOCK();
    if (pGraphNode == nullptr || pMemsetParams == nullptr ||
        (pMemsetParams->elementSize != 1 && pMemsetParams->elementSize != 2 && pMemsetParams->elementSize != 4)) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemset;
    node->memset = *pMemsetParams;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphAddHostNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                                 size_t numDependencies, const struct cudaHostNodeParams *pNodeParams) {
    API_LOCK();
    if (pGraphNode == nullptr || pNodeParams == nullptr || pNodeParams->fn == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeHost;
    node->host = *pNodeParams;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphAddChildGraphNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                       const cudaGraphNode_t *pDependencies, size_t numDependencies,
                                       cudaGraph_t childGraph) {
    API_LOCK();
    if (pGraphNode == nullptr || childGraph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    if (hasMemoryNodes(*childGraph)) {
        // only when the parent takes the child graph over (cudaGraphAddNode, cudaGraphChildGraphOwnershipMove)
        return recordError(cudaErrorNotSupported);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeGraph;
    node->child = cloneGraph(*childGraph, nullptr);
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphAddEmptyNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                                  size_t numDependencies) {
    API_LOCK();
    if (pGraphNode == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeEmpty;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

static cudaError_t addEventNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                                size_t numDependencies, cudaEvent_t event, cudaGraphNodeType type) {
    API_LOCK();
    if (pGraphNode == nullptr || event == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = type;
    node->event = event;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphAddEventRecordNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                        const cudaGraphNode_t *pDependencies, size_t numDependencies,
                                        cudaEvent_t event) {
    return addEventNode(pGraphNode, graph, pDependencies, numDependencies, event, cudaGraphNodeTypeEventRecord);
}

cudaError_t cudaGraphAddEventWaitNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                      const cudaGraphNode_t *pDependencies, size_t numDependencies, cudaEvent_t event) {
    return addEventNode(pGraphNode, graph, pDependencies, numDependencies, event, cudaGraphNodeTypeWaitEvent);
}

cudaError_t cudaGraphAddDependencies(cudaGraph_t graph, const cudaGraphNode_t *from, const cudaGraphNode_t *to,
                                     const cudaGraphEdgeData *edgeData, size_t numDependencies) {
    API_LOCK();
    if (graph == nullptr || (numDependencies > 0 && (from == nullptr || to == nullptr))) {
        return recordError(cudaErrorInvalidValue);
    }
    for (size_t i = 0; i < numDependencies; i++) {
        if (!belongs(graph, from[i]) || !belongs(graph, to[i]) || from[i] == to[i] ||
            !validEdge(from[i]->type, to[i]->type, edgeData != nullptr ? &edgeData[i] : nullptr)) {
            return recordError(cudaErrorInvalidValue);
        }
    }
    for (size_t i = 0; i < numDependencies; i++) {
        addEdge(from[i], to[i], edgeData != nullptr ? &edgeData[i] : nullptr);
    }
    return cudaSuccess;
}

cudaError_t cudaGraphRemoveDependencies(cudaGraph_t graph, const cudaGraphNode_t *from, const cudaGraphNode_t *to,
                                        const cudaGraphEdgeData *edgeData, size_t numDependencies) {
    API_LOCK();
    for (size_t i = 0; i < numDependencies; i++) {
        if (!belongs(graph, from[i]) || !belongs(graph, to[i])) {
            return recordError(cudaErrorInvalidValue);
        }
        auto &deps = to[i]->dependencies;
        auto it = std::find(deps.begin(), deps.end(), from[i]);
        // the edge must exist (with the given data)
        if (it == deps.end() || (edgeData != nullptr &&
                                 memcmp(&to[i]->dependencyData[it - deps.begin()], &edgeData[i],
                                        sizeof(cudaGraphEdgeData)) != 0)) {
            return recordError(cudaErrorInvalidValue);
        }
        removeEdge(from[i], to[i]);
    }
    return cudaSuccess;
}

cudaError_t cudaGraphDestroyNode(cudaGraphNode_t node) {
    API_LOCK();
    if (node == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    for (CUgraphNode_st *dependency: std::vector<CUgraphNode_st *>(node->dependencies)) {
        removeEdge(dependency, node);
    }
    for (CUgraphNode_st *dependent: std::vector<CUgraphNode_st *>(node->dependents)) {
        removeEdge(node, dependent);
    }
    auto &nodes = node->graph->nodes;
    nodes.erase(std::find(nodes.begin(), nodes.end(), node));
    delete node;
    return cudaSuccess;
}

// copies a list to a caller's array: with a null array only the count
template<typename T>
static cudaError_t returnList(const std::vector<T> &list, T *out, size_t *pCount) {
    if (pCount == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    if (out != nullptr) {
        const size_t n = std::min(*pCount, list.size());
        std::copy(list.begin(), list.begin() + n, out);
        for (size_t i = n; i < *pCount; i++) {
            out[i] = T{};
        }
    }
    *pCount = list.size();
    return cudaSuccess;
}

/**
 * Copies edge data to the caller's array; without an array, edges with non-default data make the query lossy
 */
static cudaError_t returnEdgeData(const std::vector<cudaGraphEdgeData> &data, cudaGraphEdgeData *out, size_t capacity,
                                  bool listed) {
    if (out == nullptr) {
        for (const cudaGraphEdgeData &d: data) {
            if (listed && (d.type != 0 || d.from_port != 0 || d.to_port != 0)) {
                return recordError(cudaErrorLossyQuery);
            }
        }
        return cudaSuccess;
    }
    for (size_t i = 0; i < capacity; i++) {
        out[i] = i < data.size() ? data[i] : cudaGraphEdgeData{};
    }
    return cudaSuccess;
}

cudaError_t cudaGraphGetNodes(cudaGraph_t graph, cudaGraphNode_t *nodes, size_t *numNodes) {
    API_LOCK();
    if (graph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    return returnList(graph->nodes, nodes, numNodes);
}

cudaError_t cudaGraphGetRootNodes(cudaGraph_t graph, cudaGraphNode_t *pRootNodes, size_t *pNumRootNodes) {
    API_LOCK();
    if (graph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    std::vector<CUgraphNode_st *> roots;
    for (CUgraphNode_st *node: graph->nodes) {
        if (node->dependencies.empty()) {
            roots.push_back(node);
        }
    }
    return returnList(roots, pRootNodes, pNumRootNodes);
}

cudaError_t cudaGraphGetEdges(cudaGraph_t graph, cudaGraphNode_t *from, cudaGraphNode_t *to,
                              cudaGraphEdgeData *edgeData, size_t *numEdges) {
    API_LOCK();
    if (graph == nullptr || numEdges == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    std::vector<CUgraphNode_st *> froms, tos;
    std::vector<cudaGraphEdgeData> data;
    for (CUgraphNode_st *node: graph->nodes) {
        for (CUgraphNode_st *dependent: node->dependents) {
            froms.push_back(node);
            tos.push_back(dependent);
            data.push_back(::edgeData(node, dependent));
        }
    }
    if ((from == nullptr) != (to == nullptr)) {
        return recordError(cudaErrorInvalidValue);
    }
    size_t count = *numEdges;
    RT_CHECK(returnList(froms, from, &count));
    count = *numEdges;
    RT_CHECK(returnList(tos, to, &count));
    const cudaError_t error = returnEdgeData(data, edgeData, from != nullptr ? *numEdges : 0, from != nullptr);
    *numEdges = froms.size();
    return error;
}

cudaError_t cudaGraphNodeGetDependencies(cudaGraphNode_t node, cudaGraphNode_t *pDependencies,
                                         cudaGraphEdgeData *edgeData, size_t *pNumDependencies) {
    API_LOCK();
    if (node == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    const size_t capacity = pDependencies != nullptr && pNumDependencies != nullptr ? *pNumDependencies : 0;
    RT_CHECK(returnList(node->dependencies, pDependencies, pNumDependencies));
    return returnEdgeData(node->dependencyData, edgeData, capacity, pDependencies != nullptr);
}

cudaError_t cudaGraphNodeGetDependentNodes(cudaGraphNode_t node, cudaGraphNode_t *pDependentNodes,
                                           cudaGraphEdgeData *edgeData, size_t *pNumDependentNodes) {
    API_LOCK();
    if (node == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    const size_t capacity = pDependentNodes != nullptr && pNumDependentNodes != nullptr ? *pNumDependentNodes : 0;
    std::vector<cudaGraphEdgeData> data;
    for (const CUgraphNode_st *dependent: node->dependents) {
        data.push_back(::edgeData(node, dependent));
    }
    RT_CHECK(returnList(node->dependents, pDependentNodes, pNumDependentNodes));
    return returnEdgeData(data, edgeData, capacity, pDependentNodes != nullptr);
}

cudaError_t cudaGraphNodeGetType(cudaGraphNode_t node, enum cudaGraphNodeType *pType) {
    if (node == nullptr || pType == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *pType = node->type;
    return cudaSuccess;
}

static cudaError_t checkNode(cudaGraphNode_t node, cudaGraphNodeType type, const void *params) {
    if (node == nullptr || params == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    return node->type == type ? cudaSuccess : recordError(cudaErrorInvalidValue);
}

cudaError_t cudaGraphKernelNodeGetParams(cudaGraphNode_t node, struct cudaKernelNodeParams *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeKernel, pNodeParams));
    pNodeParams->func = const_cast<void *>(node->func);
    pNodeParams->gridDim = node->grid;
    pNodeParams->blockDim = node->block;
    pNodeParams->sharedMemBytes = node->sharedMem;
    pNodeParams->kernelParams = node->argPtrs.empty() ? nullptr : node->argPtrs.data();
    pNodeParams->extra = nullptr;
    return cudaSuccess;
}

cudaError_t cudaGraphKernelNodeSetParams(cudaGraphNode_t node, const struct cudaKernelNodeParams *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeKernel, pNodeParams));
    if (pNodeParams->extra != nullptr) {
        return recordError(cudaErrorNotSupported);
    }
    return setKernel(node, pNodeParams->func, pNodeParams->gridDim, pNodeParams->blockDim,
                     pNodeParams->sharedMemBytes, pNodeParams->kernelParams, t_device);
}

cudaError_t cudaGraphMemcpyNodeGetParams(cudaGraphNode_t node, struct cudaMemcpy3DParms *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeMemcpy, pNodeParams));
    *pNodeParams = node->copy;
    return cudaSuccess;
}

cudaError_t cudaGraphMemcpyNodeSetParams(cudaGraphNode_t node, const struct cudaMemcpy3DParms *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeMemcpy, pNodeParams));
    node->copy = *pNodeParams;
    return cudaSuccess;
}

cudaError_t cudaGraphMemcpyNodeSetParams1D(cudaGraphNode_t node, void *dst, const void *src, size_t count,
                                           enum cudaMemcpyKind) {
    const cudaMemcpy3DParms p = linearCopy(dst, src, count);
    return cudaGraphMemcpyNodeSetParams(node, &p);
}

cudaError_t cudaGraphMemsetNodeGetParams(cudaGraphNode_t node, struct cudaMemsetParams *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeMemset, pNodeParams));
    *pNodeParams = node->memset;
    return cudaSuccess;
}

cudaError_t cudaGraphMemsetNodeSetParams(cudaGraphNode_t node, const struct cudaMemsetParams *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeMemset, pNodeParams));
    node->memset = *pNodeParams;
    return cudaSuccess;
}

cudaError_t cudaGraphHostNodeGetParams(cudaGraphNode_t node, struct cudaHostNodeParams *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeHost, pNodeParams));
    *pNodeParams = node->host;
    return cudaSuccess;
}

cudaError_t cudaGraphHostNodeSetParams(cudaGraphNode_t node, const struct cudaHostNodeParams *pNodeParams) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeHost, pNodeParams));
    node->host = *pNodeParams;
    return cudaSuccess;
}

cudaError_t cudaGraphChildGraphNodeGetGraph(cudaGraphNode_t node, cudaGraph_t *pGraph) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeGraph, pGraph));
    *pGraph = node->child;
    return cudaSuccess;
}

cudaError_t cudaGraphDebugDotPrint(cudaGraph_t graph, const char *path, unsigned int) {
    API_LOCK();
    if (graph == nullptr || path == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    FILE *file = fopen(path, "w");
    if (file == nullptr) {
        return recordError(cudaErrorOperatingSystem);
    }
    static const char *names[] = {"kernel", "memcpy", "memset", "host", "graph", "empty", "wait event",
                                  "event record", "semaphore signal", "semaphore wait", "mem alloc", "mem free",
                                  "node", "conditional"};
    std::unordered_map<const CUgraphNode_st *, size_t> index;
    fprintf(file, "digraph cudaGraph {\n");
    for (const CUgraphNode_st *node: graph->nodes) {
        index[node] = index.size();
        const char *name = node->type < sizeof(names) / sizeof(names[0]) ? names[node->type] : "node";
        fprintf(file, "  n%zu [label=\"%zu: %s\"];\n", index[node], index[node], name);
    }
    for (const CUgraphNode_st *node: graph->nodes) {
        for (const CUgraphNode_st *dependent: node->dependents) {
            fprintf(file, "  n%zu -> n%zu;\n", index[node], index[dependent]);
        }
    }
    fprintf(file, "}\n");
    fclose(file);
    return cudaSuccess;
}

// ---- executable graphs

// the memory allocations of a graph's nodes (also in child graphs)
static void graphAllocations(const CUgraph_st &graph, std::vector<GraphAllocation *> *pOut) {
    for (const CUgraphNode_st *node: graph.nodes) {
        if (node->allocation != nullptr) {
            pOut->push_back(node->allocation.get());
        }
        if (node->child != nullptr) {
            graphAllocations(*node->child, pOut);
        }
    }
}

static cudaError_t instantiate(cudaGraphExec_t *pGraphExec, cudaGraph_t graph, unsigned long long flags,
                               cudaGraphInstantiateResult *pResult = nullptr) {
    if (pResult != nullptr) {
        *pResult = cudaGraphInstantiateError;
    }
    if (pGraphExec == nullptr || graph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    // like CUDA: one executable graph at a time for graphs with memory allocations
    std::vector<GraphAllocation *> allocations;
    graphAllocations(*graph, &allocations);
    for (const GraphAllocation *allocation: allocations) {
        if (allocation->execs > 0) {
            return recordError(cudaErrorNotSupported);
        }
    }
    auto *exec = new CUgraphExec_st{};
    exec->flags = flags;
    CUgraph_st *clone = cloneGraph(*graph, &exec->clones);
    exec->graph.nodes = std::move(clone->nodes);
    exec->graph.userObjects = std::move(clone->userObjects);
    exec->graph.conditionalHandles = std::move(clone->conditionalHandles);
    for (CUgraphNode_st *node: exec->graph.nodes) {
        node->graph = &exec->graph;
    }
    clone->nodes.clear();
    clone->userObjects.clear();
    delete clone;
    if (!topologicalOrder(exec->graph, &exec->order)) {
        delete exec;
        if (pResult != nullptr) {
            *pResult = cudaGraphInstantiateInvalidStructure;
        }
        return recordError(cudaErrorInvalidValue); // a cycle
    }
    if (flags & cudaGraphInstantiateFlagDeviceLaunch) {
        // like CUDA: graphs launched from the device contain kernels, copies and fills only
        for (const CUgraphNode_st *node: exec->graph.nodes) {
            if (node->type != cudaGraphNodeTypeKernel && node->type != cudaGraphNodeTypeMemcpy &&
                node->type != cudaGraphNodeTypeMemset && node->type != cudaGraphNodeTypeEmpty) {
                delete exec;
                if (pResult != nullptr) {
                    *pResult = cudaGraphInstantiateNodeOperationNotSupported;
                }
                return recordError(cudaErrorInvalidValue);
            }
        }
    }
    assignLanes(exec);
    computeSegments(exec);
    g_liveExecs.insert(exec);
    for (GraphAllocation *allocation: allocations) {
        allocation->execs++;
    }
    if (pResult != nullptr) {
        *pResult = cudaGraphInstantiateSuccess;
    }
    *pGraphExec = exec;
    return cudaSuccess;
}

cudaError_t cudaGraphInstantiate(cudaGraphExec_t *pGraphExec, cudaGraph_t graph, unsigned long long flags) {
    API_LOCK();
    return instantiate(pGraphExec, graph, flags);
}

cudaError_t cudaGraphInstantiateWithFlags(cudaGraphExec_t *pGraphExec, cudaGraph_t graph, unsigned long long flags) {
    API_LOCK();
    return instantiate(pGraphExec, graph, flags);
}

cudaError_t cudaGraphInstantiateWithParams(cudaGraphExec_t *pGraphExec, cudaGraph_t graph,
                                           cudaGraphInstantiateParams *instantiateParams) {
    API_LOCK();
    if (instantiateParams == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    instantiateParams->errNode_out = nullptr;
    RT_CHECK(instantiate(pGraphExec, graph, instantiateParams->flags, &instantiateParams->result_out));
    if (instantiateParams->flags & cudaGraphInstantiateFlagUpload) {
        return cudaGraphUpload(*pGraphExec, instantiateParams->uploadStream);
    }
    return cudaSuccess;
}

cudaError_t cudaGraphExecGetFlags(cudaGraphExec_t graphExec, unsigned long long *flags) {
    API_LOCK();
    if (graphExec == nullptr || flags == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *flags = graphExec->flags;
    return cudaSuccess;
}

cudaError_t cudaGraphExecDestroy(cudaGraphExec_t graphExec) {
    API_LOCK();
    if (graphExec == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    g_liveExecs.erase(graphExec);
    destroySegmentLists(graphExec);
    destroyLaneResources(graphExec);
    std::vector<GraphAllocation *> allocations;
    graphAllocations(graphExec->graph, &allocations);
    for (GraphAllocation *allocation: allocations) {
        allocation->execs--;
    }
    delete graphExec;
    return cudaSuccess;
}

cudaError_t cudaGraphUpload(cudaGraphExec_t graphExec, cudaStream_t) {
    // nothing to upload: graphs replay through the regular launch paths
    return graphExec == nullptr ? recordError(cudaErrorInvalidValue) : cudaSuccess;
}

cudaError_t cudaGraphLaunch(cudaGraphExec_t graphExec, cudaStream_t handle) {
    API_LOCK();
    if (graphExec == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (capturing(stream)) {
        // like CUDA here: graph launches can't be captured
        return captureUnsupported(stream);
    }
    return launchExec(graphExec, handle, stream);
}

cudaError_t cudaGraphExecKernelNodeSetParams(cudaGraphExec_t hGraphExec, cudaGraphNode_t node,
                                             const struct cudaKernelNodeParams *pNodeParams) {
    API_LOCK();
    if (hGraphExec == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto it = hGraphExec->clones.find(node);
    if (it == hGraphExec->clones.end() || it->second->type != cudaGraphNodeTypeKernel || pNodeParams == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    hGraphExec->segmentsStale = true;
    return setKernel(it->second, pNodeParams->func, pNodeParams->gridDim, pNodeParams->blockDim,
                     pNodeParams->sharedMemBytes, pNodeParams->kernelParams, t_device);
}

cudaError_t cudaGraphExecUpdate(cudaGraphExec_t hGraphExec, cudaGraph_t hGraph,
                                cudaGraphExecUpdateResultInfo *resultInfo) {
    API_LOCK();
    if (hGraphExec == nullptr || hGraph == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto fail = [&](cudaGraphExecUpdateResult result, cudaGraphNode_t node) {
        if (resultInfo != nullptr) {
            resultInfo->result = result;
            resultInfo->errorNode = node;
            resultInfo->errorFromNode = nullptr;
        }
        return recordError(cudaErrorGraphExecUpdateFailure);
    };
    if (hasMemoryNodes(*hGraph) || hasMemoryNodes(hGraphExec->graph)) {
        return fail(cudaGraphExecUpdateErrorNotSupported, nullptr);
    }
    // the graph must have the executable graph's topology: nodes matched in topological order
    std::vector<CUgraphNode_st *> order;
    if (!topologicalOrder(*hGraph, &order) || order.size() != hGraphExec->order.size()) {
        return fail(cudaGraphExecUpdateErrorTopologyChanged, nullptr);
    }
    std::unordered_map<const CUgraphNode_st *, size_t> position, exec_position;
    for (size_t i = 0; i < order.size(); i++) {
        position[order[i]] = i;
        exec_position[hGraphExec->order[i]] = i;
    }
    for (size_t i = 0; i < order.size(); i++) {
        const CUgraphNode_st *node = order[i], *exec = hGraphExec->order[i];
        if (node->type != exec->type) {
            return fail(cudaGraphExecUpdateErrorNodeTypeChanged, order[i]);
        }
        std::vector<size_t> a, b;
        for (const CUgraphNode_st *d: node->dependencies) {
            a.push_back(position[d]);
        }
        for (const CUgraphNode_st *d: exec->dependencies) {
            b.push_back(exec_position[d]);
        }
        std::sort(a.begin(), a.end());
        std::sort(b.begin(), b.end());
        if (a != b) {
            return fail(cudaGraphExecUpdateErrorTopologyChanged, order[i]);
        }
    }
    // take over the parameters
    hGraphExec->segmentsStale = true;
    hGraphExec->clones.clear();
    for (size_t i = 0; i < order.size(); i++) {
        CUgraphNode_st *exec = hGraphExec->order[i];
        const CUgraphNode_st *node = order[i];
        exec->func = node->func;
        exec->grid = node->grid;
        exec->block = node->block;
        exec->sharedMem = node->sharedMem;
        exec->cooperative = node->cooperative;
        exec->hasCluster = node->hasCluster;
        exec->cluster = node->cluster;
        exec->args = node->args;
        exec->argOffsets = node->argOffsets;
        rebuildArgPointers(exec);
        exec->copy = node->copy;
        exec->memset = node->memset;
        exec->host = node->host;
        exec->event = node->event;
        exec->attributes = node->attributes;
        exec->conditional = node->conditional;
        exec->conditionalType = node->conditionalType;
        if (!node->bodies.empty()) {
            for (CUgraph_st *body: exec->bodies) {
                delete body;
            }
            exec->bodies.clear();
            for (const CUgraph_st *body: node->bodies) {
                exec->bodies.push_back(cloneGraph(*body, nullptr));
            }
        }
        if (node->child != nullptr) {
            delete exec->child;
            exec->child = cloneGraph(*node->child, nullptr);
        }
        hGraphExec->clones[node] = exec;
    }
    if (resultInfo != nullptr) {
        resultInfo->result = cudaGraphExecUpdateSuccess;
        resultInfo->errorNode = nullptr;
        resultInfo->errorFromNode = nullptr;
    }
    return cudaSuccess;
}

// ---- memory nodes

cudaError_t cudaGraphAddMemAllocNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                     const cudaGraphNode_t *pDependencies, size_t numDependencies,
                                     struct cudaMemAllocNodeParams *nodeParams) {
    API_LOCK();
    RT_CHECK(initialize());
    if (pGraphNode == nullptr || graph == nullptr || nodeParams == nullptr ||
        nodeParams->poolProps.allocType != cudaMemAllocationTypePinned ||
        nodeParams->poolProps.location.type != cudaMemLocationTypeDevice ||
        (numDependencies > 0 && pDependencies == nullptr)) {
        return recordError(cudaErrorInvalidValue);
    }
    for (size_t i = 0; i < numDependencies; i++) {
        if (!belongs(graph, pDependencies[i])) {
            return recordError(cudaErrorInvalidValue);
        }
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemAlloc;
    const cudaError_t error = newGraphAllocation(nodeParams->poolProps.location.id, nodeParams->bytesize,
                                                 &node->allocation);
    if (error != cudaSuccess) {
        delete node;
        return error;
    }
    nodeParams->dptr = node->allocation->ptr;
    node->allocParams = *nodeParams;
    // peer access descriptions aren't kept (graph memory is accessible like other device memory)
    node->allocParams.accessDescs = nullptr;
    node->allocParams.accessDescCount = 0;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphAddMemFreeNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                    const cudaGraphNode_t *pDependencies, size_t numDependencies, void *dptr) {
    API_LOCK();
    // only graph memory (like CUDA)
    if (pGraphNode == nullptr || !isGraphAllocation(dptr)) {
        return recordError(cudaErrorInvalidValue);
    }
    auto *node = new CUgraphNode_st{};
    node->type = cudaGraphNodeTypeMemFree;
    node->freePtr = dptr;
    return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
}

cudaError_t cudaGraphMemAllocNodeGetParams(cudaGraphNode_t node, struct cudaMemAllocNodeParams *params_out) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeMemAlloc, params_out));
    *params_out = node->allocParams;
    return cudaSuccess;
}

cudaError_t cudaGraphMemFreeNodeGetParams(cudaGraphNode_t node, void *dptr_out) {
    API_LOCK();
    RT_CHECK(checkNode(node, cudaGraphNodeTypeMemFree, dptr_out));
    *static_cast<void **>(dptr_out) = node->freePtr;
    return cudaSuccess;
}

static cudaError_t graphMemDevice(int device) {
    RT_CHECK(initialize());
    return device >= 0 && device < static_cast<int>(g_devices.size()) ? cudaSuccess
                                                                       : recordError(cudaErrorInvalidDevice);
}

cudaError_t cudaDeviceGraphMemTrim(int device) {
    API_LOCK();
    // graph memory is released when its graphs are destroyed; nothing is cached beyond that
    return graphMemDevice(device);
}

cudaError_t cudaDeviceGetGraphMemAttribute(int device, enum cudaGraphMemAttributeType attr, void *value) {
    API_LOCK();
    RT_CHECK(graphMemDevice(device));
    if (value == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    const DeviceState &state = g_devices[device];
    switch (attr) {
        case cudaGraphMemAttrUsedMemCurrent:
        case cudaGraphMemAttrReservedMemCurrent:
            *static_cast<unsigned long long *>(value) = state.graphMemUsed;
            return cudaSuccess;
        case cudaGraphMemAttrUsedMemHigh:
        case cudaGraphMemAttrReservedMemHigh:
            *static_cast<unsigned long long *>(value) = state.graphMemHigh;
            return cudaSuccess;
        default:
            return recordError(cudaErrorInvalidValue);
    }
}

cudaError_t cudaDeviceSetGraphMemAttribute(int device, enum cudaGraphMemAttributeType attr, void *value) {
    API_LOCK();
    RT_CHECK(graphMemDevice(device));
    // only resetting the high watermarks (to 0)
    if (value == nullptr || *static_cast<unsigned long long *>(value) != 0 ||
        (attr != cudaGraphMemAttrUsedMemHigh && attr != cudaGraphMemAttrReservedMemHigh)) {
        return recordError(cudaErrorInvalidValue);
    }
    g_devices[device].graphMemHigh = g_devices[device].graphMemUsed;
    return cudaSuccess;
}

// ---- generic node parameters (cudaGraphNodeParams)

static cudaError_t addConditionalNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph,
                                      const cudaGraphNode_t *pDependencies, size_t numDependencies,
                                      cudaConditionalNodeParams &params);

cudaError_t cudaGraphAddNode(cudaGraphNode_t *pGraphNode, cudaGraph_t graph, const cudaGraphNode_t *pDependencies,
                             const cudaGraphEdgeData *dependencyData, size_t numDependencies,
                             struct cudaGraphNodeParams *nodeParams) {
    API_LOCK();
    if (nodeParams == nullptr || (numDependencies > 0 && pDependencies == nullptr)) {
        return recordError(cudaErrorInvalidValue);
    }
    if (dependencyData != nullptr) {
        // the node is created without dependencies, then connected with the edge data
        for (size_t i = 0; i < numDependencies; i++) {
            if (!belongs(graph, pDependencies[i]) ||
                !validEdge(pDependencies[i]->type, nodeParams->type, &dependencyData[i])) {
                return recordError(cudaErrorInvalidValue);
            }
        }
        RT_CHECK(cudaGraphAddNode(pGraphNode, graph, nullptr, nullptr, 0, nodeParams));
        for (size_t i = 0; i < numDependencies; i++) {
            addEdge(pDependencies[i], *pGraphNode, &dependencyData[i]);
        }
        return cudaSuccess;
    }
    switch (nodeParams->type) {
        case cudaGraphNodeTypeKernel: {
            const cudaKernelNodeParamsV2 &k = nodeParams->kernel;
            if (k.functionType != cudaKernelFunctionTypeUnspecified &&
                k.functionType != cudaKernelFunctionTypeDeviceEntry) {
                return recordError(cudaErrorNotSupported);
            }
            cudaKernelNodeParams params{};
            params.func = k.func;
            params.gridDim = k.gridDim;
            params.blockDim = k.blockDim;
            params.sharedMemBytes = k.sharedMemBytes;
            params.kernelParams = k.kernelParams;
            params.extra = k.extra;
            return cudaGraphAddKernelNode(pGraphNode, graph, pDependencies, numDependencies, &params);
        }
        case cudaGraphNodeTypeMemcpy:
            if (nodeParams->memcpy.flags != 0) {
                return recordError(cudaErrorInvalidValue);
            }
            return cudaGraphAddMemcpyNode(pGraphNode, graph, pDependencies, numDependencies,
                                          &nodeParams->memcpy.copyParams);
        case cudaGraphNodeTypeMemset: {
            const cudaMemsetParamsV2 &m = nodeParams->memset;
            const cudaMemsetParams params{m.dst, m.pitch, m.value, m.elementSize, m.width, m.height};
            return cudaGraphAddMemsetNode(pGraphNode, graph, pDependencies, numDependencies, &params);
        }
        case cudaGraphNodeTypeHost: {
            const cudaHostNodeParams params{nodeParams->host.fn, nodeParams->host.userData};
            return cudaGraphAddHostNode(pGraphNode, graph, pDependencies, numDependencies, &params);
        }
        case cudaGraphNodeTypeGraph:
            if (nodeParams->graph.ownership == cudaGraphChildGraphOwnershipMove) {
                // the node takes the child graph over (the handle stays valid until the parent is destroyed)
                if (pGraphNode == nullptr || nodeParams->graph.graph == nullptr) {
                    return recordError(cudaErrorInvalidValue);
                }
                auto *node = new CUgraphNode_st{};
                node->type = cudaGraphNodeTypeGraph;
                node->child = nodeParams->graph.graph;
                return addNode(graph, node, pDependencies, numDependencies, pGraphNode);
            }
            return cudaGraphAddChildGraphNode(pGraphNode, graph, pDependencies, numDependencies,
                                              nodeParams->graph.graph);
        case cudaGraphNodeTypeEmpty:
            return cudaGraphAddEmptyNode(pGraphNode, graph, pDependencies, numDependencies);
        case cudaGraphNodeTypeWaitEvent:
            return cudaGraphAddEventWaitNode(pGraphNode, graph, pDependencies, numDependencies,
                                             nodeParams->eventWait.event);
        case cudaGraphNodeTypeEventRecord:
            return cudaGraphAddEventRecordNode(pGraphNode, graph, pDependencies, numDependencies,
                                               nodeParams->eventRecord.event);
        case cudaGraphNodeTypeMemAlloc: {
            const cudaMemAllocNodeParamsV2 &a = nodeParams->alloc;
            cudaMemAllocNodeParams params{a.poolProps, a.accessDescs, a.accessDescCount, a.bytesize, nullptr};
            RT_CHECK(cudaGraphAddMemAllocNode(pGraphNode, graph, pDependencies, numDependencies, &params));
            nodeParams->alloc.dptr = params.dptr;
            return cudaSuccess;
        }
        case cudaGraphNodeTypeMemFree:
            return cudaGraphAddMemFreeNode(pGraphNode, graph, pDependencies, numDependencies, nodeParams->free.dptr);
        case cudaGraphNodeTypeConditional:
            return addConditionalNode(pGraphNode, graph, pDependencies, numDependencies, nodeParams->conditional);
        default:
            // external semaphores
            return recordError(cudaErrorNotSupported);
    }
}

cudaError_t cudaGraphNodeGetParams(cudaGraphNode_t node, struct cudaGraphNodeParams *nodeParams) {
    API_LOCK();
    if (node == nullptr || nodeParams == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    memset(nodeParams, 0, sizeof(*nodeParams));
    nodeParams->type = node->type;
    switch (node->type) {
        case cudaGraphNodeTypeKernel: {
            cudaKernelNodeParamsV2 &k = nodeParams->kernel;
            k.func = const_cast<void *>(node->func);
            k.gridDim = node->grid;
            k.blockDim = node->block;
            k.sharedMemBytes = node->sharedMem;
            k.kernelParams = node->argPtrs.data();
            k.functionType = cudaKernelFunctionTypeDeviceEntry;
            break;
        }
        case cudaGraphNodeTypeMemcpy:
            nodeParams->memcpy.copyParams = node->copy;
            break;
        case cudaGraphNodeTypeMemset: {
            const cudaMemsetParams &m = node->memset;
            cudaMemsetParamsV2 &out = nodeParams->memset;
            out.dst = m.dst;
            out.pitch = m.pitch;
            out.value = m.value;
            out.elementSize = m.elementSize;
            out.width = m.width;
            out.height = m.height;
            break;
        }
        case cudaGraphNodeTypeHost:
            nodeParams->host.fn = node->host.fn;
            nodeParams->host.userData = node->host.userData;
            break;
        case cudaGraphNodeTypeGraph:
            nodeParams->graph.graph = node->child;
            break;
        case cudaGraphNodeTypeWaitEvent:
            nodeParams->eventWait.event = node->event;
            break;
        case cudaGraphNodeTypeEventRecord:
            nodeParams->eventRecord.event = node->event;
            break;
        case cudaGraphNodeTypeMemAlloc: {
            const cudaMemAllocNodeParams &a = node->allocParams;
            nodeParams->alloc.poolProps = a.poolProps;
            nodeParams->alloc.bytesize = a.bytesize;
            nodeParams->alloc.dptr = a.dptr;
            break;
        }
        case cudaGraphNodeTypeMemFree:
            nodeParams->free.dptr = node->freePtr;
            break;
        case cudaGraphNodeTypeConditional:
            nodeParams->conditional.handle = reinterpret_cast<unsigned long long>(node->conditional->slot);
            nodeParams->conditional.type = node->conditionalType;
            nodeParams->conditional.size = static_cast<unsigned int>(node->bodies.size());
            nodeParams->conditional.phGraph_out = node->bodies.data();
            break;
        default:
            break;
    }
    return cudaSuccess;
}

/**
 * Changes a node's parameters (of a graph or an executable graph); its type stays
 */
static cudaError_t setNodeParams(CUgraphNode_st *node, const cudaGraphNodeParams *p) {
    if (p == nullptr || p->type != node->type) {
        return recordError(cudaErrorInvalidValue);
    }
    switch (node->type) {
        case cudaGraphNodeTypeKernel: {
            const cudaKernelNodeParamsV2 &k = p->kernel;
            if ((k.functionType != cudaKernelFunctionTypeUnspecified &&
                 k.functionType != cudaKernelFunctionTypeDeviceEntry) || k.extra != nullptr) {
                return recordError(cudaErrorNotSupported);
            }
            return setKernel(node, k.func, k.gridDim, k.blockDim, k.sharedMemBytes, k.kernelParams, t_device);
        }
        case cudaGraphNodeTypeMemcpy:
            node->copy = p->memcpy.copyParams;
            return cudaSuccess;
        case cudaGraphNodeTypeMemset: {
            const cudaMemsetParamsV2 &m = p->memset;
            if (m.elementSize != 1 && m.elementSize != 2 && m.elementSize != 4) {
                return recordError(cudaErrorInvalidValue);
            }
            node->memset = cudaMemsetParams{m.dst, m.pitch, m.value, m.elementSize, m.width, m.height};
            return cudaSuccess;
        }
        case cudaGraphNodeTypeHost:
            if (p->host.fn == nullptr) {
                return recordError(cudaErrorInvalidValue);
            }
            node->host = cudaHostNodeParams{p->host.fn, p->host.userData};
            return cudaSuccess;
        case cudaGraphNodeTypeWaitEvent:
        case cudaGraphNodeTypeEventRecord: {
            cudaEvent_t event = node->type == cudaGraphNodeTypeWaitEvent ? p->eventWait.event : p->eventRecord.event;
            if (event == nullptr) {
                return recordError(cudaErrorInvalidValue);
            }
            node->event = event;
            return cudaSuccess;
        }
        case cudaGraphNodeTypeEmpty:
            return cudaSuccess;
        default:
            // child graphs (cudaGraphExecChildGraphNodeSetParams), memory nodes
            return recordError(cudaErrorNotSupported);
    }
}

cudaError_t cudaGraphNodeSetParams(cudaGraphNode_t node, struct cudaGraphNodeParams *nodeParams) {
    API_LOCK();
    if (node == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    return setNodeParams(node, nodeParams);
}

// the copy of a graph's node in the executable graph, of the given type
static cudaError_t execNode(cudaGraphExec_t exec, cudaGraphNode_t node, int type, CUgraphNode_st **pOut) {
    if (exec == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    auto it = exec->clones.find(node);
    if (it == exec->clones.end() || (type >= 0 && it->second->type != type)) {
        return recordError(cudaErrorInvalidValue);
    }
    *pOut = it->second;
    // the node's prebuilt commands are rebuilt at the next launch
    exec->segmentsStale = true;
    return cudaSuccess;
}

cudaError_t cudaGraphExecNodeSetParams(cudaGraphExec_t graphExec, cudaGraphNode_t node,
                                       struct cudaGraphNodeParams *nodeParams) {
    API_LOCK();
    CUgraphNode_st *clone{};
    RT_CHECK(execNode(graphExec, node, -1, &clone));
    return setNodeParams(clone, nodeParams);
}

